/// Processes a batch of items with the given transformer and returns results.
pub fn process_batch_{i}(items: Vec<Item>, transformer: &Transformer, config: &Config) -> Result<Vec<Result>> {{
    let mut results = Vec::with_capacity(items.len());
    for item in items {{
        let transformed = transformer.apply(item, config)?;
        if transformed.score() < config.threshold {{
            continue;
        }}
        results.push(transformed);
    }}
    results.sort_by(|a, b| b.score().cmp(&a.score()));
    Ok(results)
}}
''')
