for i in range(20):
    open(f'src/mod{i}.py','w').write(f'''
def compute_metrics_{i}(values, weights, options=None):
    """Compute weighted metrics for the given values."""
    if not values:
        return {{}}
    total_weight = sum(weights)
    if total_weight == 0:
        raise ValueError("weights must not sum to zero")
    metrics = {{}}
    for name, value in zip(values, weights):
        metrics[name] = value / total_weight * (options.get(name, 1) if options else 1)
    return metrics
''')
EOF
