{"command": "cat <<'PYEOF' > /tmp/probe.py
import subprocess,time,os,sys,shutil

def cap(name):
    p=subprocess.run(["tmux","capture-pane","-t",name,"-p"],capture_output=True)
    return p.stdout.decode().split("\n")

def launch(name,wd,args,x=100,y=30):
    subprocess.run(["tmux","kill-session","-t",name],stderr=subprocess.DEVNULL)
    subprocess.run(["tmux","new-session","-d","-x",str(x),"-y",str(y),"-s",name,
                    "timeout 600 /workspace/executable %s"%args],cwd=wd,capture_output=True)
    time.sleep(2.5)

def cycle(name,order=("Easy","Normal","Hard","Wild","Zen")):
    # order: difficulties in cycle order starting after 4 Rights from Normal
    res={}
    for d in order:
        res[d]=None
        time.sleep(1.3)
        lines=cap(name)
        for l in lines[13:18]:
            if "challenges available" in l:
                res[d]=int(l.strip().split()[0])
        time.sleep(0.5)
        subprocess.run(["tmux","send-keys","-t",name,"Right"])
    return res

def probe(wd,args,name="ex"):
    launch(name,wd,args)
    res=cycle(name)
    subprocess.run(["tmux","kill-session","-t",name],stderr=subprocess.DEVNULL)
    return res

if __name__=="__main__":
    print(probe(sys.argv[1], sys.argv[2] if len(sys.argv)>2 else "."))
