import subprocess,time,os,sys,shutil,re

def cap(name):
    p=subprocess.run(["tmux","capture-pane","-t",name,"-p"],capture_output=True)
    return p.stdout.decode().split("\n")

def launch(name,wd,args,x=100,y=30):
    subprocess.run(["tmux","kill-session","-t",name],stderr=subprocess.DEVNULL)
    subprocess.run(["tmux","new-session","-d","-x",str(x),"-y",str(y),"-s",name,
                    "timeout 600 /workspace/executable %s"%args],cwd=wd,capture_output=True)
    time.sleep(3)

def state(name):
    lines=cap(name)
    diff=None;cnt=None
    for l in lines[10:20]:
        m=re.search(r"Difficulty: (.) (\w+) (.)",l)
        if m: diff=m.group(2)
        if "challenges available" in l: cnt=int(l.strip().split()[0])
    return diff,cnt

def probe(wd,args,name="ex",keys=6):
    launch(name,wd,args)
    res=[]
    for i in range(keys):
        time.sleep(1.3); res.append(state(name))
        time.sleep(0.3); subprocess.run(["tmux","send-keys","-t",name,"Right"])
    subprocess.run(["tmux","kill-session","-t",name],stderr=subprocess.DEVNULL)
    return res

if __name__=="__main__":
    for r in probe(sys.argv[1], sys.argv[2] if len(sys.argv)>2 else "."): print(r)
