{"command": "cat <<'PYEOF' > /tmp/dumpall.py
import subprocess,time,sys,re
def cap(n):
    p=subprocess.run(["tmux","capture-pane","-t",n,"-p"],capture_output=True)
    return p.stdout.decode().split("\n")
def send(n,k):
    subprocess.run(["tmux","send-keys","-t",n,k])
def dump(n):
    seen=[];prev=None
    for i in range(120):
        lines=cap(n)
        t="\n".join(lines[3:56])
        if t==prev: break
        prev=t
        for l in lines[3:56]:
            seen.append(l.rstrip())
        send(n,"Down"); time.sleep(0.06)
    out=[]
    for l in seen:
        if out and out[-1]==l: continue
        out.append(l)
    return out
name=sys.argv[1]
w=int(sys.argv[2]) if len(sys.argv)>2 else 5
res=[]
for i in range(w):
    res.append("\n".join(dump(name)))
    send(name,"Right"); time.sleep(0.4)
for i,r in enumerate(res):
    print("="*20,"TAB",i+1,"="*20)
    print(r)
