import subprocess,time,sys,re
def cap(n):
    p=subprocess.run(["tmux","capture-pane","-t",n,"-p"],capture_output=True)
    return p.stdout.decode().split("\n")
def send(n,k):
    subprocess.run(["tmux","send-keys","-t",n,k])
TABS=["CLI Usage","Scoring System","Rank System","Game Help","Community","About & Credits","Third-Party"]
def curtab(n):
    for l in cap(n)[1:4]:
        if "Scoring System" in l or "CLI Usage" in l:
            m=re.search(r"(Scoring System|CLI Usage|Rank System|Game Help|Community|About & Credits|Third-Party)",l)
            if m: return m.group(1)
    return None
def gototab(n,t):
    for _ in range(8):
        c=curtab(n)
        if c==t: return True
        send(n,"Right"); time.sleep(0.3)
    return False
def dump(n, maxdown=120):
    seen=[];prev=None
    for i in range(maxdown):
        lines=cap(n)
        t="\n".join(lines[3:56])
        if t==prev: break
        prev=t
        for l in lines[3:56]:
            seen.append(l.rstrip())
        send(n,"Down"); time.sleep(0.05)
    out=[]
    for l in seen:
        if out and out[-1]==l: continue
        out.append(l)
    return out
if __name__=="__main__":
    name=sys.argv[1]
    for t in TABS:
        ok=gototab(name,t)
        send(n=name,k="Down") if False else None
        r=dump(name)
        fn="/tmp/h_"+t.replace(" & ","_").replace(" ","_").lower()+".txt"
        open(fn,"w").write("\n".join(r))
        print(fn, len(r), ok)
