import subprocess,time,sys
def cape(n):
    p=subprocess.run(["tmux","capture-pane","-t",n,"-p","-e"],capture_output=True)
    return p.stdout.decode().split("\n")
def cap(n):
    p=subprocess.run(["tmux","capture-pane","-t",n,"-p"],capture_output=True)
    return p.stdout.decode().split("\n")
def send(n,k): subprocess.run(["tmux","send-keys","-t",n,k])
name=sys.argv[1]
for ti in range(7):
    lines=cap(name)
    top=None;bot=None
    for i,l in enumerate(lines):
        if l.startswith("┌"): top=i
        if l.startswith("└"): bot=i
    body=lines[top+1:bot]
    st=subprocess.run(["tmux","capture-pane","-t",name,"-p","-e"],capture_output=True).stdout.decode().split("\n")
    # active tab
    act=None
    import re
    for l in st[top+1:top+2]:
        m=re.search(r"\x1b\[1m\x1b\[38;2;([0-9;]+)m([^\x1b]+)\x1b\[0m",l)
        if m: act=m.group(2).strip()
    fn="/tmp/b_%s.txt"%(act.replace(" & ","_").replace(" ","_").lower())
    open(fn,"w").write("\n".join(body))
    print(fn, len(body), top, bot)
    send(name,"Right"); time.sleep(0.6)
