import subprocess,time,sys,re
def cape(n):
    p=subprocess.run(["tmux","capture-pane","-t",n,"-p","-e"],capture_output=True)
    return p.stdout.decode().split("\n")
def cap(n,lo=1,hi=30):
    p=subprocess.run(["tmux","capture-pane","-t",n,"-p"],capture_output=True)
    return p.stdout.decode().split("\n")[lo-1:hi]
def send(n,k): subprocess.run(["tmux","send-keys","-t",n,k])
def sendl(n,s): subprocess.run(["tmux","send-keys","-t",n,"-l",s])
def parse(n):
    """return list of (ch, kind) for code area; kind in typed/cursor/mistake/untyped"""
    lines=cape(n)
    out=[]
    for l in lines:
        if not l.startswith(" "): continue
        # only code box content lines: they contain ' │ ' number prefix pattern
        if "\u2502" not in l: continue
        # find segment after '│ ' of line numbers
        parts=re.split(r"(\x1b\[[0-9;]*m)", l)
        buf=[];cur=None
        for p in parts:
            if p.startswith("\x1b["):
                m=re.match(r"\x1b\[(\d+)(?:;(\d+);(\d+);(\d+))?m",p)
                if m:
                    v=m.group(1)
                    if v=="38" and m.group(2)=="2": cur=("fg",m.group(2),m.group(3),m.group(4))
                    elif v=="48" and m.group(2)=="2": cur=("bg",m.group(2),m.group(3),m.group(4))
                    elif v=="39": cur=("fg",None,None,None)
                    elif v=="49": cur=("bg",None,None,None)
                continue
            for ch in p:
                buf.append((ch,cur))
        out.append(buf)
    return out
def state(n):
    lines=cape(n)
    info=[]
    for l in lines:
        if "\x1b[48;2;" in l or "\x1b[38;2;135;175;255m" in l:
            # strip line number prefix: find ' │ ' inside a styled span
            m=re.search(r"\x1b\[38;2;60;60;60m(   \d+ \| )|\x1b\[1m\x1b\[38;2;[0-9;]+m(   \d+ \| )",l)
            info.append(l)
    return info
PYEOF
echo ok"}

