import subprocess,time
def kill(): subprocess.run(["tmux","kill-server"],stderr=subprocess.DEVNULL)
kill(); time.sleep(0.5)
subprocess.run(["tmux","new-session","-d","-x","100","-y","30","-s","z3","timeout 600 /workspace/executable ."],cwd="/tmp/e1")
time.sleep(4)
for i in range(4): subprocess.run(["tmux","send-keys","-t","z3","Right"]); time.sleep(0.6)
subprocess.run(["tmux","send-keys","-t","z3","Space"]); time.sleep(3)
subprocess.run(["tmux","send-keys","-t","z3","Space"]); time.sleep(3.5)
def cap(i=24):
    p=subprocess.run(["tmux","capture-pane","-t","z3","-p"],capture_output=True)
    return p.stdout.decode().split("\n")[i]
def cape():
    return subprocess.run(["tmux","capture-pane","-t","z3","-p","-e"],capture_output=True).stdout.decode().split("\n")
def sendl(s): subprocess.run(["tmux","send-keys","-t","z3","-l",s])
def send(k): subprocess.run(["tmux","send-keys","-t","z3",k])
text="fn f() -> i32 {\n    let x = 1;\n//-------------------\n    x\n}\n"
for i,ch in enumerate(text):
    (sendl(ch) if ch!="\n" else send("Enter"))
    time.sleep(0.25)
    m=cap()
    if "Mistakes: 0" not in m:
        print("FIRST MISTAKE at index",i,repr(ch))
        print("   ", m)
        for l in cape()[6:9]: print("   ", l[:150].replace("\x1b","<E>"))
        break
else:
    print("no mistakes; metrics:", cap())
PY"}

