import subprocess,time
def kill(): subprocess.run(["tmux","kill-server"],stderr=subprocess.DEVNULL)
def start(name="zz",cwd="/tmp/e1",args=".",diff_rights=4):
    kill(); time.sleep(0.4)
    subprocess.run(["tmux","new-session","-d","-x","100","-y","30","-s",name,"timeout 600 /workspace/executable "+args],cwd=cwd)
    time.sleep(4)
    for i in range(diff_rights): subprocess.run(["tmux","send-keys","-t",name,"Right"]); time.sleep(0.6)
    subprocess.run(["tmux","send-keys","-t",name,"Space"]); time.sleep(3)
    subprocess.run(["tmux","send-keys","-t",name,"Space"]); time.sleep(3.5)
