def cap(n="zz",i=24):
    p=subprocess.run(["tmux","capture-pane","-t",n,"-p"],capture_output=True)
    return p.stdout.decode().split("\n")[i]
def sendl(n,s): subprocess.run(["tmux","send-keys","-t",n,"-l",s])
def send(n,k): subprocess.run(["tmux","send-keys","-t",n,k])
def show(n="zz",rows=(6,12)):
