import subprocess,re,sys
def alle(n):
    p=subprocess.run(["tmux","capture-pane","-t",n,"-p","-e"],capture_output=True)
    return p.stdout.decode().split("\n")
def cap(n):
    p=subprocess.run(["tmux","capture-pane","-t",n,"-p"],capture_output=True)
    return p.stdout.decode().split("\n")
def code_rows(n):
    """return list of raw styled rows that are code content lines (contain ' │ ' prefix)"""
    rows=[]
    for l in alle(n):
        if re.search(r"\x1b\[38;2;60;60;60m\s*\d+ \| ", l) or re.search(r"\x1b\[1m\x1b\[38;2;[0-9;]+m\s*\d+ \| ", l):
            rows.append(l)
    return rows
def tokenize(row):
    """yield (char, style) where style is a dict of fg/bg/bold"""
    st={"fg":None,"bg":None,"bold":False}
    out=[]
    i=0
    while i<len(row):
        m=re.match(r"\x1b\[(\d+)(?:;(\d+);(\d+);(\d+))?m", row[i:])
        if m:
            v=m.group(1)
            if v=="38": st["fg"]=m.group(3)
            elif v=="48": st["bg"]=m.group(3)
            elif v=="39": st["fg"]=None
            elif v=="49": st["bg"]=None
            elif v=="1": st["bold"]=True
            elif v=="0": st={"fg":None,"bg":None,"bold":False}
            i+=m.end()
        else:
            out.append((row[i], dict(st)))
            i+=1
    return out
def state(n):
    rows=code_rows(n)
    lines=[]
    for r in rows:
        toks=tokenize(r)
        # find line number prefix: chars until the second ' │ '
        # build string and find the pattern '   N │ '
        s="".join(t[0] for t in toks)
        m=re.search(r"(\s*\d+) \| ", s)
        if not m: 
            lines.append(None); continue
        idx=m.end()
        body=toks[idx:]
        # strip trailing padding spaces (the filler is unstyled with fg None)
        lines.append(body)
    return lines
def cursor_index(n):
    lines=state(n)
    c=0
    for li,body in enumerate(lines):
        if body is None: continue
        for j,(ch,st) in enumerate(body):
            if st["bg"] is not None:  # cursor or mistake highlight
                # text index: sum of previous line bodies + newlines
                return c+j, ch, st, li
        # advance c by body length (excluding trailing whitespace padding)
        # count chars until the first unstyled padding run
        k=0
        for (ch,st) in body:
            if st["fg"] is None and ch==" ":
                break
            k+=1
        c+=k
        if k>0 and body[k-1][0]=="\u21b5": pass
    return None,None,None,None
