use clap::{Arg, ArgAction, Command};

pub const SUPPORTED_LANGS: &str = "rust, typescript, javascript, python, ruby, go, swift, kotlin, java, php, csharp, c, cpp, haskell, dart, scala, zig";

pub const LONG_ABOUT: &str = "GitType turns your own source code into typing challenges. Practice typing by using functions, classes, and methods from your actual projects. \n\nExamples:\n  gittype                           # Use current directory\n  gittype /path/to/repo             # Use specific repository\n  gittype --repo owner/repo         # Clone and use GitHub repository\n  gittype --langs rust,python       # Filter by languages";

pub const ABOUT: &str = "A typing practice tool using your own code repositories - extracts all code chunks (functions, classes, methods, etc.)";

#[derive(Debug, Clone, PartialEq)]
pub struct Cli {
    pub repo_path: Option<String>,
    pub repo: Option<String>,
    pub langs: Option<String>,
    pub command: Option<SubCommand>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum SubCommand {
    History,
    Stats,
    Export { format: String, output: Option<String> },
    Cache(CacheCommand),
    Repo(RepoCommand),
    Trending { language: Option<String>, repo_name: Option<String>, period: String },
}

#[derive(Debug, Clone, PartialEq)]
pub enum CacheCommand {
    Stats,
    Clear,
    List,
}

#[derive(Debug, Clone, PartialEq)]
pub enum RepoCommand {
    List,
    Clear { force: bool },
    Play,
}

fn build_cli() -> Command {
    let cache = Command::new("cache")
        .about("Manage challenge cache")
        .subcommand(Command::new("stats").about("Show cache statistics"))
        .subcommand(Command::new("clear").about("Clear all cached challenges"))
        .subcommand(Command::new("list").about("List cached repository keys"))
        .arg(Arg::new("help").short('h').long("help").help("Print help"));
    let repo = Command::new("repo")
        .about("Manage repositories")
        .subcommand(Command::new("list").about("List all cached repositories"))
        .subcommand(
            Command::new("clear")
                .about("Clear all cached repositories")
                .arg(Arg::new("force").long("force").action(ArgAction::SetTrue).help("Force clear without confirmation")),
        )
        .subcommand(Command::new("play").about("Play a cached repository interactively"))
        .arg(Arg::new("help").short('h').long("help").help("Print help"));
    let trending = Command::new("trending")
        .about("Select and practice with trending repositories from GitHub")
        .arg(
            Arg::new("language")
                .value_name("LANGUAGE")
                .long_help("Programming language to filter trending repositories.\nSupported languages: C, C#, C++, Dart, Go, Haskell, Java, JavaScript, Kotlin, PHP, Python, Ruby, Rust, Scala, Swift, TypeScript, Zig"),
        )
        .arg(Arg::new("repo_name").value_name("REPO_NAME").long_help("Specific repository name to select from trending list"))
        .arg(
            Arg::new("period")
                .long("period")
                .value_name("PERIOD")
                .default_value("daily")
                .long_help("Time period for trending (daily, weekly, monthly)"),
        )
        .arg(Arg::new("help").short('h').long("help").help("Print help"));
    Command::new("gittype")
        .version("0.8.0")
        .about(ABOUT)
        .long_about(LONG_ABOUT)
        .subcommand(Command::new("history").about("Show session history"))
        .subcommand(Command::new("stats").about("Show analytics"))
        .subcommand(
            Command::new("export")
                .about("Export session data")
                .arg(Arg::new("format").long("format").value_name("FORMAT").default_value("json").help("Export format"))
                .arg(Arg::new("output").long("output").value_name("OUTPUT").help("Output file path"))
                .arg(Arg::new("help").short('h').long("help").help("Print help")),
        )
        .subcommand(cache)
        .subcommand(repo)
        .subcommand(trending)
        .arg(Arg::new("repo_path").value_name("REPO_PATH").long_help("Repository path to extract code from"))
        .arg(
            Arg::new("repo")
                .long("repo")
                .value_name("REPO")
                .long_help("GitHub repository URL or path to clone and play with. Supports formats:\n  - owner/repo\n  - https://github.com/owner/repo\n  - git@github.com:owner/repo.git"),
        )
        .arg(
            Arg::new("langs")
                .long("langs")
                .value_name("LANGS")
                .long_help("Filter by programming languages (comma-separated). Supported languages:\n  rust, typescript, javascript, python, ruby, go, swift, kotlin, java, php, csharp, c, cpp, haskell, dart, scala, zig\n  Example: --langs rust,python,typescript"),
        )
        .arg(Arg::new("help").short('h').long("help").action(ArgAction::Count).help("Print help (see more with '--help')").long_help("Print help (see a summary with '-h')"))
        .arg(Arg::new("version").short('V').long("version").action(ArgAction::Version).help("Print version"))
}

pub fn parse_args() -> Result<Cli, String> {
    let mut cmd = build_cli();
    let m = match cmd.clone().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            let _ = e.print();
            std::process::exit(if e.use_stderr() { 2 } else { 0 });
        }
    };
    let _ = &mut cmd;
    if m.get_flag("version") {
        println!("gittype 0.8.0");
        std::process::exit(0);
    }
    let command = if let Some((name, sub)) = m.subcommand() {
        match name {
            "history" => Some(SubCommand::History),
            "stats" => Some(SubCommand::Stats),
            "export" => Some(SubCommand::Export {
                format: sub.get_one::<String>("format").cloned().unwrap_or_else(|| "json".into()),
                output: sub.get_one::<String>("output").cloned(),
            }),
            "cache" => Some(SubCommand::Cache(match sub.subcommand() {
                Some(("stats", _)) => CacheCommand::Stats,
                Some(("clear", _)) => CacheCommand::Clear,
                Some(("list", _)) => CacheCommand::List,
                _ => {
                    let mut c = build_cli();
                    let sc = c.find_subcommand_mut("cache").unwrap();
                    let _ = sc.print_help();
                    std::process::exit(0);
                }
            })),
            "repo" => Some(SubCommand::Repo(match sub.subcommand() {
                Some(("list", _)) => RepoCommand::List,
                Some(("clear", s)) => RepoCommand::Clear { force: s.get_flag("force") },
                Some(("play", _)) => RepoCommand::Play,
                _ => {
                    let mut c = build_cli();
                    let sc = c.find_subcommand_mut("repo").unwrap();
                    let _ = sc.print_help();
                    std::process::exit(0);
                }
            })),
            "trending" => Some(SubCommand::Trending {
                language: sub.get_one::<String>("language").cloned(),
                repo_name: sub.get_one::<String>("repo_name").cloned(),
                period: sub.get_one::<String>("period").cloned().unwrap_or_else(|| "daily".into()),
            }),
            _ => None,
        }
    } else {
        None
    };
    Ok(Cli {
        repo_path: m.get_one::<String>("repo_path").cloned(),
        repo: m.get_one::<String>("repo").cloned(),
        langs: m.get_one::<String>("langs").cloned(),
        command,
    })
}
