use std::fmt;

#[derive(Debug)]
pub enum GitTypeError {
    TerminalError(String),
    ExtractionError(String),
    IoError(String),
    General(String),
}

impl fmt::Display for GitTypeError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            GitTypeError::TerminalError(m) => write!(f, "Terminal error: {}", m),
            GitTypeError::ExtractionError(m) => write!(f, "Failed to extract code chunks: {}", m),
            GitTypeError::IoError(m) => write!(f, "I/O error: {}", m),
            GitTypeError::General(m) => write!(f, "{}", m),
        }
    }
}

pub type AppResult<T> = Result<T, GitTypeError>;

/// Write the detailed error report to ./gittype_error_<ts>.log (append) and
/// print the "💾 Error details written to: ..." hint on stderr.
