use std::fs::{File, OpenOptions};
use std::io::Write;
use std::sync::{Mutex, OnceLock};
use chrono::Local;

static LOGGER: OnceLock<Mutex<Option<File>>> = OnceLock::new();

fn logger() -> &'static Mutex<Option<File>> {
    LOGGER.get_or_init(|| Mutex::new(None))
}

pub fn init() {
    let dir = match dirs::home_dir() {
        Some(h) => h.join(".gittype").join("logs"),
        None => return,
    };
    let _ = std::fs::create_dir_all(&dir);
    let ts = Local::now().format("%Y%m%d_%H%M%S");
    let path = dir.join(format!("gittype_{}.log", ts));
    let file = OpenOptions::new().create(true).append(true).open(&path).ok();
    *logger().lock().unwrap() = file;
    info("gittype::infrastructure::logging", &format!("GitType logging initialized, logs saved to: {}", dir.display()));
}

fn write(level: &str, module: &str, msg: &str) {
    if let Ok(mut guard) = logger().lock() {
        if let Some(f) = guard.as_mut() {
            let _ = writeln!(f, "{} [{}] {} - {}", Local::now().format("%Y-%m-%d %H:%M:%S"), level, module, msg);
        }
    }
}

pub fn info(module: &str, msg: &str) { write("INFO", module, msg); }
pub fn warn(module: &str, msg: &str) { write("WARN", module, msg); }
pub fn error(module: &str, msg: &str) { write("ERROR", module, msg); }

pub fn log_application_error(err: &crate::error::GitTypeError) {
    let now = chrono::Utc::now();
    let executable = std::env::args().next().unwrap_or_default();
    let wd = std::env::current_dir().map(|p| p.display().to_string()).unwrap_or_default();
    let args: Vec<String> = std::env::args().collect();
    let args_str = format!("[{}]", args.iter().map(|a| format!("\"{}\"", a)).collect::<Vec<_>>().join(", "));
    let block = format!(
        "APPLICATION ERROR:\nERROR OCCURRED AT: {} UTC\nERROR TYPE: \"gittype::domain::error::GitTypeError\"\nERROR MESSAGE: {}\nEXECUTABLE: \"{}\"\nWORKING_DIR: \"{}\"\nCOMMAND_ARGS: {}\nOS: {}\nARCH: {}\n",
        now.format("%Y-%m-%d %H:%M:%S"), err, executable, wd, args_str, std::env::consts::OS, std::env::consts::ARCH
    );
    error("gittype::infrastructure::logging", &block);
}
