pub fn load_theme(id: &str) -> Option<ThemeDef> {
    for (i, t) in THEME_IDS.iter().enumerate() {
        if *t == id {
            return serde_json::from_str::<ThemeDef>(THEME_JSONS[i]).ok();
        }
    }
    // custom theme
    if let Some(home) = dirs::home_dir() {
        let p = home.join(".gittype").join("custom-theme.json");
        if let Ok(s) = std::fs::read_to_string(&p) {
            #[derive(Deserialize)]
            struct Custom { dark: Palette, light: Palette }
            if let Ok(c) = serde_json::from_str::<Custom>(&s) {
                return Some(ThemeDef { id: "custom".into(), name: "Custom".into(), description: "Custom theme".into(), dark: c.dark, light: c.light });
            }
        }
    }
    None
}

pub fn default_theme() -> ThemeColors {
    let t = load_theme("default").unwrap();
    ThemeColors { dark: t.dark, light: t.light, dark_mode: true }
}

pub fn write_custom_theme() {
    if let Some(home) = dirs::home_dir() {
        let dir = home.join(".gittype");
        let _ = std::fs::create_dir_all(&dir);
        let p = dir.join("custom-theme.json");
        if !p.exists() {
            if let Ok(t) = serde_json::from_str::<ThemeDef>(THEME_JSONS[0]) {
                let _ = serde_json::to_string_pretty(&CustomPalette { dark: t.dark, light: t.light }).map(|s| std::fs::write(&p, s));
            }
        }
    }
}

