    pub lang_scala: Rgb, pub lang_haskell: Rgb, pub lang_dart: Rgb, pub lang_zig: Rgb,
    pub lang_clojure: Rgb, pub lang_default: Rgb,
}

pub fn lang_color(language: &str, dark_mode: bool) -> Color {
    let json = if dark_mode { LANG_DARK_JSON } else { LANG_LIGHT_JSON };
    let p: LangPalette = match serde_json::from_str(json) { Ok(p) => p, Err(_) => return Color::White };
    let c = match language {
        "rust" => p.lang_rust, "python" => p.lang_python, "javascript" | "js" | "jsx" => p.lang_javascript,
        "typescript" | "ts" | "tsx" => p.lang_typescript, "go" => p.lang_go, "java" => p.lang_java,
        "c" => p.lang_c, "cpp" | "c++" => p.lang_cpp, "csharp" | "c#" => p.lang_csharp,
        "php" => p.lang_php, "ruby" => p.lang_ruby, "swift" => p.lang_swift,
        "kotlin" => p.lang_kotlin, "scala" => p.lang_scala, "haskell" => p.lang_haskell,
        "dart" => p.lang_dart, "zig" => p.lang_zig, "clojure" => p.lang_clojure, _ => p.lang_default,
    };
    c.color()
}
