use std::path::{Path, PathBuf};
use std::process::Command;

#[derive(Debug, Clone)]
pub struct RepoInfo {
    pub root: PathBuf,
    pub remote_url: Option<String>,
    pub branch: Option<String>,
    pub commit: Option<String>,
    pub dirty: bool,
}

fn git(root: &Path, args: &[&str]) -> Option<String> {
    let out = Command::new("git").arg("-C").arg(root).args(args)
        .output().ok()?;
    if !out.status.success() { return None; }
    let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
    if s.is_empty() { None } else { Some(s) }
}

/// Resolve the repository root the same way the original does: the given path
/// is always interpreted relative to the current working directory (plain
/// string join), so absolute paths end up inside a doubled directory.
pub fn resolve_root(repo_path: Option<&str>) -> PathBuf {
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    match repo_path {
        Some(p) => {
            let joined = if p.starts_with('/') {
                format!("{}/{}", cwd.display(), p)
            } else {
                format!("{}/{}", cwd.display(), p)
            };
            PathBuf::from(joined)
        }
        None => cwd,
    }
}

pub fn is_git_repo(root: &Path) -> bool {
    root.join(".git").exists() || git(root, &["rev-parse", "--git-dir"]).is_some()
}

pub fn repo_info(root: &Path) -> RepoInfo {
    let remote_url = git(root, &["config", "--get", "remote.origin.url"]);
    let branch = git(root, &["rev-parse", "--abbrev-ref", "HEAD"]);
    let commit = git(root, &["rev-parse", "HEAD"]);
    let dirty = git(root, &["status", "--porcelain"]).map(|s| !s.is_empty()).unwrap_or(false);
    RepoInfo { root: root.to_path_buf(), remote_url, branch, commit, dirty }
}

impl RepoInfo {
    /// "user/name" used in the UI footer
    pub fn display_name(&self) -> String {
        match parse_remote(self.remote_url.as_deref()) {
            Some((u, n)) => format!("{}/{}", u, n),
            None => "local/unknown".to_string(),
        }
    }
    pub fn user_name(&self) -> String {
        match parse_remote(self.remote_url.as_deref()) { Some((u, _)) => u, None => "local".into() }
    }
    pub fn repository_name(&self) -> String {
        match parse_remote(self.remote_url.as_deref()) { Some((_, n)) => n, None => "unknown".into() }
    }
    /// key used by the challenge cache, e.g. `github_com_a_b`
    pub fn cache_key_prefix(&self) -> String {
        match parse_remote(self.remote_url.as_deref()) {
            Some((u, n)) => normalize(&format!("{}/{}/{}", host_of(self.remote_url.as_deref()), u, n)),
            None => "file____".to_string(),
        }
    }
    pub fn cache_key(&self, commit: &str) -> String {
        format!("{}:{}", self.cache_key_prefix(), commit)
    }
}

fn host_of(url: Option<&str>) -> String {
    let url = match url { Some(u) => u, None => return String::new() };
    for p in ["https://", "http://"] {
        if let Some(rest) = url.strip_prefix(p) {
            return rest.split('/').next().unwrap_or("").to_string();
        }
    }
    String::new()
}

/// Parse a remote url into (user, name). Returns None when it cannot be parsed.
pub fn parse_remote(url: Option<&str>) -> Option<(String, String)> {
    let url = url?;
    let s = if let Some(rest) = url.strip_prefix("https://").or_else(|| url.strip_prefix("http://")) {
        let rest = rest.strip_suffix(".git").unwrap_or(rest);
        let mut it = rest.splitn(3, '/');
        let _host = it.next()?;
        let a = it.next()?;
        let b = it.next().unwrap_or("");
        return Some((a.to_string(), b.to_string()));
    } else if let Some(rest) = url.strip_prefix("git@") {
        let (host, path) = match rest.split_once(':') { Some(v) => v, None => return None };
        let _ = host;
        let path = path.strip_suffix(".git").unwrap_or(path);
        let parts: Vec<&str> = path.split('/').filter(|p| !p.is_empty()).collect();
        if parts.is_empty() { return None; }
        return Some((parts[0].to_string(), parts[1..].join("/")));
    } else {
        return None;
    };
    Some(s)
}

pub fn normalize(s: &str) -> String {
    s.chars().map(|c| if c == '/' || c == '.' || c == ':' { '_' } else { c }).collect()
}
RSEOF
echo ok"}

