use std::path::Path;

#[derive(Debug, Clone)]
pub struct Chunk {
    pub file: String,
    pub start_line: usize, // 1-based, inclusive
    pub end_line: usize,   // 1-based, inclusive
    pub language: String,
    pub content: String,
    pub is_file: bool,
}

pub const EXT_LANG: &[(&str, &str)] = &[
    ("rs", "rust"), ("py", "python"), ("js", "javascript"), ("jsx", "javascript"),
    ("ts", "typescript"), ("tsx", "typescript"), ("mjs", "javascript"), ("go", "go"),
    ("rb", "ruby"), ("swift", "swift"), ("kt", "kotlin"), ("java", "java"), ("php", "php"),
    ("cs", "csharp"), ("c", "c"), ("h", "c"), ("cc", "cpp"), ("cpp", "cpp"), ("cxx", "cpp"),
    ("hpp", "cpp"), ("hxx", "cpp"), ("hs", "haskell"), ("dart", "dart"), ("scala", "scala"),
    ("zig", "zig"), ("clj", "clojure"), ("cljs", "clojure"),
];

pub fn lang_for_ext(ext: &str) -> Option<&'static str> {
    EXT_LANG.iter().find(|(e, _)| *e == ext).map(|(_, l)| *l)
}

pub fn lang_for_file(name: &str) -> Option<&'static str> {
    let ext = name.rsplit('.').next().unwrap_or("");
    if ext == name { return None; }
    lang_for_ext(ext)
}

pub fn display_language(lang: &str) -> String {
    match lang {
        "rust" => "Rust", "python" => "Python", "javascript" => "JavaScript",
        "typescript" => "TypeScript", "go" => "Go", "java" => "Java", "c" => "C",
        "cpp" => "C++", "csharp" => "C#", "php" => "PHP", "ruby" => "Ruby",
        "swift" => "Swift", "kotlin" => "Kotlin", "scala" => "Scala", "haskell" => "Haskell",
        "dart" => "Dart", "zig" => "Zig", "clojure" => "Clojure", _ => lang,
    }.to_string()
}

const MAX_FILE_SIZE: u64 = 1024 * 1024;

fn is_ignored(path: &Path, name: &str) -> bool {
    let skip_dirs = ["node_modules", "target", ".git", "dist", "build", "vendor", "__pycache__",
        ".venv", "venv", ".idea", ".vscode", "out", "bin", "obj", ".next", "coverage"];
    for c in path.components() {
        if let std::path::Component::Normal(os) = c {
            let s = os.to_string_lossy();
            if skip_dirs.iter().any(|d| *d == s) { return true; }
            if s.starts_with('.') && s.len() > 1 && !s.starts_with("..") { return true; }
        }
    }
    let _ = name;
    false
}

pub fn collect_files(root: &Path, langs: Option<&Vec<String>>) -> Vec<(PathBufStr, String)> {
    let mut out = Vec::new();
    walk(root, root, &mut out, langs, 0);
    out.sort();
    out
}

type PathBufStr = (String, String);

fn walk(root: &Path, dir: &Path, out: &mut Vec<PathBufStr>, langs: &Option<Vec<String>>, depth: usize) {
    if depth > 24 { return; }
    let rd = match std::fs::read_dir(dir) { Ok(r) => r, Err(_) => return };
    let mut entries: Vec<_> = rd.filter_map(|e| e.ok()).collect();
    entries.sort_by_key(|e| e.file_name());
    for e in entries {
        let p = e.path();
        let name = e.file_name().to_string_lossy().to_string();
        if name.starts_with('.') && name != ".gitignore" { continue; }
        if p.is_dir() {
            if is_ignored(&p, &name) { continue; }
            walk(root, &p, out, langs, depth + 1);
        } else if p.is_file() {
            if is_ignored(&p, &name) { continue; }
            let lang = match lang_for_file(&name) { Some(l) => l, None => continue };
            if let Some(ls) = langs {
                if !ls.iter().any(|x| x.eq_ignore_ascii_case(lang)) { continue; }
            }
            match e.metadata() {
                Ok(m) if m.len() > MAX_FILE_SIZE => {
                    crate::logging::warn("gittype::domain::services::source_code_parser::source_code_parser",
                        &format!("Skipping large file: {:?} ({}MB > 1MB limit)", relative(root, &p), m.len() / (1024*1024)));
                    continue;
                }
                Ok(_) => {}
                Err(_) => continue,
            }
            let rel = relative(root, &p).replace('\\', "/");
            out.push((rel, lang.to_string()));
        }
    }
}

fn relative(root: &Path, p: &Path) -> String {
    p.strip_prefix(root).map(|r| r.display().to_string()).unwrap_or_else(|_| p.display().to_string())
}

fn brace_match(lines: &[&str], start: usize, open_col: usize) -> Option<usize> {
    let mut depth = 0i32;
    let mut started = false;
    for (i, line) in lines.iter().enumerate().skip(start) {
        let bytes: Vec<char> = line.chars().collect();
        let from = if i == start { open_col } else { 0 };
        let mut j = from;
        let mut in_str: Option<char> = None;
        while j < bytes.len() {
            let c = bytes[j];
            if let Some(q) = in_str {
                if c == '\\' { j += 2; continue; }
                if c == q { in_str = None; }
                j += 1; continue;
            }
            match c {
                '"' | '\'' => { in_str = Some(c); j += 1; }
                '/' if j + 1 < bytes.len() && bytes[j+1] == '/' => { break; }
                '{' => { depth += 1; started = true; j += 1; }
                '}' => { depth -= 1; j += 1; if started && depth == 0 { return Some(i); } }
                _ => { j += 1; }
            }
        }
        let _ = bytes;
    }
    None
}

fn block_head(line: &str) -> Option<usize> {
    // returns the column of the first '{' if the line looks like a block start
    let t = line.trim_start();
    if t.starts_with("//") || t.starts_with('*') || t.starts_with("/*") || t.starts_with("#") { return None; }
    if !t.contains('{') { return None; }
    let open = line.find('{')?;
    Some(open)
}

const FN_PATTERNS: &[&str] = &[
    "fn ", "func ", "def ", "function ", "public ", "private ", "protected ", "static ",
    "async ", "operator ", "constructor", "impl ", "trait ", "struct ", "class ", "enum ",
    "interface ", "namespace ", "module ", "type ", "extension ", "record ", "object ",
    "package ", "data ", "sealed ", "abstract ", "final ", "pub ", "export ", "const ",
    "let ", "var ", "val ", "sub ", "end", "for ", "while ", "if ", "else", "match ",
    "switch ", "case ", "try ", "catch ", "do ", "elif", "unless", "when ", "do {", "init(",
];

fn looks_like_block(line: &str) -> bool {
    let t = line.trim_start();
    if t.is_empty() { return false; }
    FN_PATTERNS.iter().any(|p| t.starts_with(p) || t.contains(&format!(" {}", p)))
        || t.starts_with("@") || t.ends_with('{')
}

pub fn extract(path: &str, lang: &str, content: &str) -> Vec<Chunk> {
    let mut chunks: Vec<Chunk> = Vec::new();
    let lines: Vec<&str> = content.split('\n').collect();
    let python = lang == "python";
    if python {
        extract_indent(&path.to_string(), lang, &lines, &mut chunks, vec!['d', 'c', 'f', 'i', 'w', 't', 'e']);
    } else if lang == "haskell" {
        extract_indent(&path.to_string(), lang, &lines, &mut chunks, vec!['d', 't']);
    } else {
        // brace based
        let mut i = 0usize;
        while i < lines.len() {
            let line = lines[i];
            if let Some(open) = block_head(line) {
                if looks_like_block(line) {
                    if let Some(end) = brace_match(&lines, i, open) {
                        let content2 = lines[i..=end].join("\n") + "\n";
                        chunks.push(Chunk {
                            file: path.to_string(), start_line: i + 1, end_line: end + 1,
                            language: lang.to_string(), content: content2, is_file: false,
                        });
                    }
                }
            }
            i += 1;
        }
    }
    // whole file chunk
    chunks.push(Chunk {
        file: path.to_string(), start_line: 1, end_line: lines.len().saturating_sub(1).max(1),
        language: lang.to_string(), content: content.to_string(), is_file: true,
    });
    // dedup by content, keeping the first occurrence
    let mut seen = std::collections::HashSet::new();
    chunks.retain(|c| {
        let key = format!("{}\u{1}{}", c.file, c.content);
        seen.insert(key)
    });
    chunks.retain(|c| c.content.chars().count() >= 10);
    chunks
}

fn indent_of(line: &str) -> usize { line.len() - line.trim_start().len() }

fn extract_indent(file: &str, lang: &str, lines: &[&str], out: &mut Vec<Chunk>, kinds: Vec<char>) {
    let kw = kinds;
    let mut i = 0usize;
    while i < lines.len() {
        let line = lines[i];
        let t = line.trim_start();
        if t.is_empty() || t.starts_with('#') { i += 1; continue; }
        let ind = indent_of(line);
        let first = t.chars().next().unwrap_or(' ');
        let is_kw = t.split(|c: char| c == ' ' || c == '(').next().map(|w| w.chars().next().unwrap_or(' ')).map(|c| kw.contains(&c)).unwrap_or(false);
        let is_def = t.starts_with("def ") || t.starts_with("class ") || t.starts_with("async def ");
        if (is_def || (is_kw && (first == 'f' || first == 'i' || first == 'w' || first == 't' || first == 'e'))) && t.ends_with(':') {
            let mut j = i + 1;
            while j < lines.len() {
                let l2 = lines[j];
                if l2.trim().is_empty() { j += 1; continue; }
                if indent_of(l2) <= ind { break; }
                j += 1;
            }
            let end = if j > i + 1 { j - 1 } else { i };
            let content = lines[i..=end].join("\n") + "\n";
            out.push(Chunk {
                file: file.to_string(), start_line: i + 1, end_line: end + 1,
                language: lang.to_string(), content, is_file: false,
            });
            i = end + 1;
        } else { i += 1; }
    }
}
