// Minimal SQLite database file reader/writer supporting the schema used by gittype.
// Only what is needed to persist sessions/results and read them back is implemented.

pub const PAGE_SIZE: usize = 4096;

pub type Row = Vec<Value>;

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Null,
    Int(i64),
    Real(f64),
    Text(String),
    Bool(bool),
}

impl Value {
    fn serial_type(&self) -> (u8, Vec<u8>) {
        match self {
            Value::Null => (0, vec![]),
            Value::Bool(b) => (1, vec![if *b { 1 } else { 0 }]),
            Value::Int(i) => {
                if *i == 0 { (8, vec![]) }
                else if *i == 1 { (9, vec![]) }
                else if *i >= -128 && *i <= 127 { (1, vec![*i as u8]) }
                else if *i >= -32768 && *i <= 32767 { (2, (*i as i16).to_be_bytes().to_vec()) }
                else if *i >= -8388608 && *i <= 8388607 {
                    let b = (*i as i32).to_be_bytes(); (3, b[1..4].to_vec())
                } else if *i >= -2147483648 && *i <= 2147483647 { (4, (*i as i32).to_be_bytes().to_vec()) }
                else { (6, (*i as i64).to_be_bytes().to_vec()) }
            }
            Value::Real(f) => (7, f.to_be_bytes().to_vec()),
            Value::Text(s) => {
                let b = s.as_bytes();
                (13 + 2 * b.len() as u8, b.to_vec())
            }
        }
    }
    pub fn as_text(&self) -> String {
        match self { Value::Text(s) => s.clone(), Value::Int(i) => i.to_string(), Value::Bool(b) => if *b { "1".into() } else { "0".into() }, Value::Real(f) => f.to_string(), Value::Null => String::new() }
    }
    pub fn as_int(&self) -> i64 { match self { Value::Int(i) => *i, Value::Bool(b) => *b as i64, Value::Text(s) => s.parse().unwrap_or(0), Value::Real(f) => *f as i64, Value::Null => 0 } }
    pub fn as_real(&self) -> f64 { match self { Value::Real(f) => *f, Value::Int(i) => *i as f64, Value::Bool(b) => if *b { 1.0 } else { 0.0 }, Value::Text(s) => s.parse().unwrap_or(0.0), Value::Null => 0.0 } }
}

fn read_varint(b: &[u8], p: &mut usize) -> i64 {
    let mut v: u64 = 0;
    for i in 0..8 {
        let byte = b[*p]; *p += 1;
        if i == 8 { v = (v << 8) | (byte as u64 & 0xff); break; }
        v = (v << 7) | (byte as u64 & 0x7f);
        if byte & 0x80 == 0 { break; }
    }
    v as i64
}

fn write_varint(v: u64, out: &mut Vec<u8>) {
    if v == 0 { out.push(0); return; }
    let mut tmp = Vec::new();
    let mut v = v;
    while v > 0 { tmp.push((v & 0x7f) as u8); v >>= 7; }
    tmp.reverse();
    for i in 0..tmp.len() {
        if i == tmp.len() - 1 { out.push(tmp[i]); } else { out.push(tmp[i] | 0x80); }
    }
}

pub struct Db {
    pub path: std::path::PathBuf,
    pub tables: Vec<Table>,
}

pub struct Table {
    pub name: String,
    pub sql: String,
    pub rows: Vec<Row>,
}

const SCHEMA: &[(&str, &str)] = &[
    ("schema_version", "CREATE TABLE schema_version (\n                version INTEGER PRIMARY KEY,\n                applied_at DATETIME DEFAULT CURRENT_TIMESTAMP\n            )"),
    ("repositories", "CREATE TABLE repositories (\n                id INTEGER PRIMARY KEY,\n                user_name TEXT NOT NULL,\n                repository_name TEXT NOT NULL,\n                remote_url TEXT NOT NULL,\n                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n                UNIQUE(user_name, repository_name)\n            )"),
    ("sessions", "CREATE TABLE sessions (\n                id INTEGER PRIMARY KEY,\n                repository_id INTEGER,\n                started_at DATETIME NOT NULL,\n                completed_at DATETIME,\n                branch TEXT,\n                commit_hash TEXT,\n                is_dirty BOOLEAN DEFAULT FALSE,\n                game_mode TEXT NOT NULL,\n                difficulty_level TEXT,\n                max_stages INTEGER,\n                time_limit_seconds INTEGER,\n                FOREIGN KEY (repository_id) REFERENCES repositories (id)\n            )"),
    ("challenges", "CREATE TABLE challenges (\n                id TEXT PRIMARY KEY,\n                file_path TEXT,\n                start_line INTEGER,\n                end_line INTEGER,\n                language TEXT,\n                code_content TEXT NOT NULL,\n                comment_ranges TEXT, -- JSON array of [start, end] ranges\n                difficulty_level TEXT,\n                created_at DATETIME DEFAULT CURRENT_TIMESTAMP\n            )"),
    ("stages", "CREATE TABLE stages (\n                id INTEGER PRIMARY KEY,\n                session_id INTEGER NOT NULL,\n                challenge_id TEXT NOT NULL,\n                stage_number INTEGER NOT NULL,\n                started_at DATETIME,\n                completed_at DATETIME,\n                FOREIGN KEY (session_id) REFERENCES sessions (id),\n                FOREIGN KEY (challenge_id) REFERENCES challenges (id)\n            )"),
    ("session_results", "CREATE TABLE session_results (\n                id INTEGER PRIMARY KEY,\n                session_id INTEGER NOT NULL,\n                repository_id INTEGER NOT NULL,      -- Denormalized for aggregation\n                keystrokes INTEGER NOT NULL,\n                mistakes INTEGER NOT NULL,\n                duration_ms INTEGER NOT NULL,\n                wpm REAL,\n                cpm REAL,\n                accuracy REAL,\n                stages_completed INTEGER NOT NULL,\n                stages_attempted INTEGER NOT NULL,\n                stages_skipped INTEGER NOT NULL,\n                partial_effort_keystrokes INTEGER DEFAULT 0,\n                partial_effort_mistakes INTEGER DEFAULT 0,\n                best_stage_wpm REAL,\n                worst_stage_wpm REAL,\n                best_stage_accuracy REAL,\n                worst_stage_accuracy REAL,\n                score REAL,\n                rank_name TEXT,\n                tier_name TEXT,\n                rank_position INTEGER,\n                rank_total INTEGER,\n                position INTEGER,\n                total INTEGER,\n                game_mode TEXT,                       -- Denormalized from sessions.game_mode\n                difficulty_level TEXT,                -- Denormalized from sessions.difficulty_level  \n                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n                FOREIGN KEY (session_id) REFERENCES sessions (id),\n                FOREIGN KEY (repository_id) REFERENCES repositories (id)\n            )"),
    ("stage_results", "CREATE TABLE stage_results (\n                id INTEGER PRIMARY KEY,\n                stage_id INTEGER NOT NULL,\n                session_id INTEGER NOT NULL,        -- Denormalized for aggregation\n                repository_id INTEGER NOT NULL,     -- Denormalized for aggregation\n                keystrokes INTEGER NOT NULL,\n                mistakes INTEGER NOT NULL,\n                duration_ms INTEGER NOT NULL,\n                wpm REAL,\n                cpm REAL,\n                accuracy REAL,\n                consistency_streaks TEXT, -- JSON array of streak lengths\n                score REAL,\n                rank_name TEXT,\n                tier_name TEXT,\n                rank_position INTEGER,\n                rank_total INTEGER,\n                position INTEGER,\n                total INTEGER,\n                was_skipped BOOLEAN DEFAULT FALSE,\n                was_failed BOOLEAN DEFAULT FALSE,\n                completed_at DATETIME NOT NULL,\n                language TEXT,                       -- Denormalized from challenges.language\n                difficulty_level TEXT,               -- Denormalized from challenges.difficulty_level\n                FOREIGN KEY (stage_id) REFERENCES stages (id),\n                FOREIGN KEY (session_id) REFERENCES sessions (id),\n                FOREIGN KEY (repository_id) REFERENCES repositories (id)\n            )"),
];

const INDEXES: &[&str] = &[
    "CREATE INDEX idx_stage_results_repo_date \n             ON stage_results(repository_id, completed_at)",
    "CREATE INDEX idx_stage_results_language \n             ON stage_results(language)",
    "CREATE INDEX idx_stage_results_session \n             ON stage_results(session_id)",
    "CREATE INDEX idx_session_results_repo_date \n             ON session_results(repository_id, created_at)",
    "CREATE INDEX idx_sessions_repo_date \n             ON sessions(repository_id, started_at)",
];

impl Db {
    pub fn open(path: std::path::PathBuf) -> Db {
        let mut db = Db { path, tables: Vec::new() };
        for (name, sql) in SCHEMA { db.tables.push(Table { name: name.to_string(), sql: sql.to_string(), rows: Vec::new() }); }
        if db.path.exists() {
            if let Ok(bytes) = std::fs::read(&db.path) {
                db.load(&bytes);
            }
        }
        db
    }

    fn load(&mut self, bytes: &[u8]) {
        if bytes.len() < 100 || &bytes[0..16] != b"SQLite format 3\0" { return; }
        let n = (bytes.len() / PAGE_SIZE).max(1);
        // page 1 contains sqlite_master rows
        let rows = read_table_leaf(bytes, 1);
        let mut schema_rows = Vec::new();
        for r in rows { schema_rows.push(r); }
        // map name -> root page
        let mut root_of = std::collections::HashMap::new();
        for r in &schema_rows {
            if r.len() >= 5 {
                let ty = r[0].as_text();
                let name = r[1].as_text();
                let root = r[3].as_int() as usize;
                if ty == "table" { root_of.insert(name, root); }
            }
        }
        for t in self.tables.iter_mut() {
            if let Some(root) = root_of.get(&t.name) {
                t.rows = read_table_leaf(bytes, *root);
            }
        }
        let _ = n;
    }

    pub fn save(&self) {
        let ntables = self.tables.len();
        let mut pages: Vec<Vec<u8>> = Vec::new();
        // page 1
        pages.push(vec![0u8; PAGE_SIZE]);
        // root pages for tables then indexes
        let mut roots = Vec::new();
        for t in &self.tables {
            let root = pages.len() + 1;
            roots.push(root);
            pages.push(build_table_leaf(&t.rows));
        }
        for _ in INDEXES { let root = pages.len() + 1; roots.push(root); pages.push(build_index_leaf()); }
        // schema rows
        let mut schema_rows: Vec<Row> = Vec::new();
        for (i, t) in self.tables.iter().enumerate() {
            schema_rows.push(vec![Value::Text("table".into()), Value::Text(t.name.clone()), Value::Text(t.name.clone()), Value::Int(roots[i] as i64), Value::Text(t.sql.clone())]);
        }
        for (k, sql) in INDEXES.iter().enumerate() {
            let name = sql.split_whitespace().nth(2).unwrap_or("idx").to_string();
            let tbl = sql.split("ON ").nth(1).unwrap_or("stage_results").split('(').next().unwrap_or("").trim().to_string();
            schema_rows.push(vec![Value::Text("index".into()), Value::Text(name), Value::Text(tbl), Value::Int(roots[ntables + k] as i64), Value::Text(sql.to_string())]);
        }
        let p1 = build_table_leaf_at(&schema_rows, 1, PAGE_SIZE);
        pages[0] = p1;
        let mut out: Vec<u8> = Vec::new();
        let total = pages.len();
        // header
        let mut hdr: Vec<u8> = Vec::new();
        hdr.extend_from_slice(b"SQLite format 3\0");
        hdr.extend_from_slice(&PAGE_SIZE.to_be_bytes());
        hdr.push(1); hdr.push(1); // write version / read version
        hdr.push(0); hdr.push(0); // reserved
        hdr.push(64); hdr.push(32); // max/min payload fraction
        hdr.push(32); // leaf payload fraction
        hdr.extend_from_slice(&0u32.to_be_bytes()); // change counter
        hdr.extend_from_slice(&total.to_be_bytes()); // db size in pages
        hdr.extend_from_slice(&0u32.to_be_bytes());
        hdr.extend_from_slice(&0u32.to_be_bytes()); // schema cookie
        hdr.extend_from_slice(&4u32.to_be_bytes()); // schema format
        hdr.extend_from_slice(&PAGE_SIZE.to_be_bytes());
        hdr.push(0); hdr.push(0); // text encoding utf8
        hdr.extend_from_slice(&0u32.to_be_bytes());
        hdr.extend_from_slice(&0u32.to_be_bytes());
        hdr.extend_from_slice(&0u32.to_be_bytes());
        hdr.extend_from_slice(&0u32.to_be_bytes());
        hdr.extend_from_slice(&0u32.to_be_bytes()); // version-for
        hdr.extend_from_slice(&0u32.to_be_bytes()); // version-against
        while hdr.len() < 100 { hdr.push(0); }
        let mut file_bytes: Vec<u8> = hdr;
        for p in pages.iter() {
            let mut page = p.clone();
            if file_bytes.len() == 0 { /* page 1 header handled below */ }
            file_bytes.extend_from_slice(&page);
        }
        // merge header into page 1
        let mut final_bytes: Vec<u8> = Vec::new();
        final_bytes.extend_from_slice(&hdr);
        let p1 = &pages[0];
        let skip = if true { 100 } else { 0 };
        final_bytes.extend_from_slice(&p1[skip..]);
        for p in pages.iter().skip(1) { final_bytes.extend_from_slice(p); }
        if final_bytes.len() % PAGE_SIZE != 0 {
            final_bytes.resize(((final_bytes.len() / PAGE_SIZE) + 1) * PAGE_SIZE, 0);
        }
        let _ = &mut out;
        let _ = std::fs::create_dir_all(self.path.parent().unwrap_or(std::path::Path::new(".")));
        let _ = std::fs::write(&self.path, final_bytes);
    }

    pub fn table(&self, name: &str) -> Option<&Table> { self.tables.iter().find(|t| t.name == name) }
    pub fn table_mut(&mut self, name: &str) -> Option<&mut Table> { self.tables.iter_mut().find(|t| t.name == name) }
    pub fn next_id(&self, name: &str) -> i64 {
        self.table(name).map(|t| t.rows.iter().map(|r| r.first().map(|v| v.as_int()).unwrap_or(0)).max().unwrap_or(0) + 1).unwrap_or(1)
    }
}

fn cell_payload(row: &Row) -> Vec<u8> {
    let mut types = Vec::new();
    let mut body = Vec::new();
    for v in row {
        let (st, data) = v.serial_type();
        types.push(st);
        body.extend_from_slice(&data);
    }
    let mut hdr = Vec::new();
    let mut hdr_len = 1 + types.len();
    // compute header length including its own varint
    loop {
        let mut probe = Vec::new();
        write_varint(hdr_len as u64, &mut probe);
        if probe.len() + types.len() == hdr_len { break; }
        hdr_len += 1;
    }
    write_varint(hdr_len as u64, &mut hdr);
    for t in types { hdr.push(t); }
    let mut out = Vec::new();
    out.extend_from_slice(&hdr);
    out.extend_from_slice(&body);
    out
}

fn build_table_leaf(rows: &[Row]) -> Vec<u8> {
    let mut page = vec![0u8; PAGE_SIZE];
    page[0] = 0x0d;
    let mut cell_offs = Vec::new();
    let mut content: Vec<u8> = Vec::new();
    let mut offset = PAGE_SIZE;
    for r in rows {
        let payload = cell_payload(r);
        let mut cell = Vec::new();
        write_varint(payload.len() as u64, &mut cell);
        cell.extend_from_slice(&payload);
        offset -= cell.len();
        cell_offs.push(offset as u16);
        content.extend_from_slice(&cell);
    }
    let ncells = cell_offs.len();
    page[1] = (ncells >> 8) as u8; page[2] = ncells as u8;
    let content_start = PAGE_SIZE - content.len();
    page[5] = (content_start >> 8) as u8; page[6] = content_start as u8;
    page[7] = 0;
    let mut pos = 8usize;
    for off in &cell_offs {
        page[pos] = (off >> 8) as u8; page[pos+1] = *off as u8; pos += 2;
    }
    let mut c = content_start;
    for cell in content.chunks(0) { let _ = cell; }
    // write cells from content_start
    let mut p = content_start;
    for r in rows {
        let payload = cell_payload(r);
        let mut cell = Vec::new();
        write_varint(payload.len() as u64, &mut cell);
        cell.extend_from_slice(&payload);
        page[p..p+cell.len()].copy_from_slice(&cell);
        p += cell.len();
    }
    page
}

fn build_table_leaf_at(rows: &[Row], _page: usize, size: usize) -> Vec<u8> {
    let mut page = build_table_leaf(rows);
    page.resize(size, 0);
    page
}

fn build_index_leaf() -> Vec<u8> { let mut page = vec![0u8; PAGE_SIZE]; page[0] = 0x0a; page }

fn read_table_leaf(bytes: &[u8], page_no: usize) -> Vec<Row> {
    let start = (page_no - 1) * PAGE_SIZE;
