fn write_leaf_page(page: &mut [u8], cells: &[(u64, Vec<u8>)]) {
    let mut offs = Vec::new();
    let mut off = PAGE_SIZE;
    let mut content = Vec::new();
    for (_, cell) in cells {
        off -= cell.len();
        offs.push(off as u16);
        content.extend_from_slice(cell);
    }
    let n = cells.len();
    page[1] = (n >> 8) as u8; page[2] = n as u8;
    let cs = PAGE_SIZE - content.len();
    page[5] = (cs >> 8) as u8; page[6] = cs as u8;
    page[7] = 0;
    let mut p = 8usize;
    for o in &offs { page[p] = (o >> 8) as u8; page[p+1] = *o as u8; p += 2; }
    let mut q = cs;
    for (_, cell) in cells {
        page[q..q+cell.len()].copy_from_slice(cell);
        q += cell.len();
    }
}

