fn build_table_tree(rows: &[Row], base: usize) -> Vec<Vec<u8>> {
    let leaves = split_cells(rows);
    if leaves.len() == 1 {
        let mut page = vec![0u8; PAGE_SIZE];
        page[0] = 0x0d;
        write_leaf_page(&mut page, &leaves[0]);
        return vec![page];
    }
    let mut pages: Vec<Vec<u8>> = Vec::new();
    let mut children = Vec::new();
