        let total = pages.len();
        let mut hdr: Vec<u8> = Vec::new();
        hdr.extend_from_slice(b"SQLite format 3\\0");
        hdr.extend_from_slice(&(PAGE_SIZE as u16).to_be_bytes());
        hdr.push(1); hdr.push(1);
        hdr.push(0);
        hdr.push(64); hdr.push(32); hdr.push(32);
        hdr.extend_from_slice(&1u32.to_be_bytes());
        hdr.extend_from_slice(&(total as u32).to_be_bytes());
        hdr.extend_from_slice(&0u32.to_be_bytes());
        hdr.extend_from_slice(&0u32.to_be_bytes());
        hdr.extend_from_slice(&1u32.to_be_bytes());
        hdr.extend_from_slice(&4u32.to_be_bytes());
        hdr.extend_from_slice(&0u32.to_be_bytes());
        hdr.extend_from_slice(&0u16.to_be_bytes());
        hdr.extend_from_slice(&1u16.to_be_bytes());
        hdr.extend_from_slice(&0u32.to_be_bytes());
        hdr.extend_from_slice(&0u32.to_be_bytes());
        hdr.extend_from_slice(&0u32.to_be_bytes());
        while hdr.len() < 92 { hdr.push(0); }
        hdr.extend_from_slice(&1u32.to_be_bytes());
        hdr.extend_from_slice(&3046000u32.to_be_bytes());
        let mut final_bytes: Vec<u8> = hdr.clone();
        final_bytes.extend_from_slice(&pages[0][100..]);
        for p in pages.iter().skip(1) { final_bytes.extend_from_slice(p); }
        if final_bytes.len() % PAGE_SIZE != 0 {
            final_bytes.resize(((final_bytes.len() / PAGE_SIZE) + 1) * PAGE_SIZE, 0);
        }
        let _ = std::fs::create_dir_all(self.path.parent().unwrap_or(std::path::Path::new(".")));
        let _ = std::fs::write(&self.path, final_bytes);
    }

