    pub fn load(&mut self) {
        let bytes = match std::fs::read(&self.path) { Ok(b) => b, Err(_) => return };
        let mut p = 0usize;
        while p + 8 <= bytes.len() {
            let nl = u32::from_be_bytes([bytes[p],bytes[p+1],bytes[p+2],bytes[p+3]]) as usize; p += 4;
            if p + nl > bytes.len() { break; }
            let name = String::from_utf8_lossy(&bytes[p..p+nl]).to_string(); p += nl;
            let nrow = u32::from_be_bytes([bytes[p],bytes[p+1],bytes[p+2],bytes[p+3]]) as usize; p += 4;
