use sha2::{Digest, Sha256};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Difficulty { Easy, Normal, Hard, Wild, Zen }

impl Difficulty {
    pub const ALL: [Difficulty; 5] = [Difficulty::Easy, Difficulty::Normal, Difficulty::Hard, Difficulty::Wild, Difficulty::Zen];
    pub fn name(&self) -> &'static str {
        match self { Difficulty::Easy => "Easy", Difficulty::Normal => "Normal", Difficulty::Hard => "Hard", Difficulty::Wild => "Wild", Difficulty::Zen => "Zen" }
    }
    pub fn target(&self) -> usize {
        match self { Difficulty::Easy => 100, Difficulty::Normal => 200, Difficulty::Hard => 500, _ => 0 }
    }
    pub fn size_hint(&self) -> &'static str {
        match self { Difficulty::Easy => "~100 characters", Difficulty::Normal => "~200 characters", Difficulty::Hard => "~500 characters", Difficulty::Wild => "Full chunks", Difficulty::Zen => "Entire files" }
    }
    pub fn desc(&self) -> &'static str {
        match self { Difficulty::Easy => "Short code snippets", Difficulty::Normal => "Medium functions", Difficulty::Hard => "Long functions or classes", Difficulty::Wild => "Unpredictable length chunks", Difficulty::Zen => "Complete files as challenges" }
    }
    pub fn from_index(i: usize) -> Difficulty { Difficulty::ALL[i % 5] }
}

#[derive(Debug, Clone)]
pub struct Challenge {
    pub id: String,
    pub file_path: String,
    pub start_line: usize,
    pub end_line: usize,
    pub language: String,
    pub content: String,
    /// 1-based line numbers of the chunk that are comment-only lines
    pub comment_lines: Vec<usize>,
    pub difficulty: Difficulty,
}

impl Challenge {
    pub fn lang_display(&self) -> String { crate::extract::display_language(&self.language) }
}

fn is_comment_line(line: &str, lang: &str) -> bool {
    let t = line.trim_start();
    if t.is_empty() { return false; }
    match lang {
        "python" => t.starts_with('#'),
        "haskell" => t.starts_with("--"),
        "ruby" => t.starts_with('#'),
        "php" => t.starts_with("//") || t.starts_with('#') || t.starts_with("/*"),
        _ => t.starts_with("//") || t.starts_with("/*") || t.starts_with('*'),
    }
}

pub fn comment_lines_of(content: &str, lang: &str) -> Vec<usize> {
    let mut out = Vec::new();
    for (i, l) in content.split('\n').enumerate() {
        if is_comment_line(l, lang) { out.push(i + 1); }
    }
    out
}

/// Take the first n whole lines whose cumulative length reaches `target`.
fn truncate_lines(content: &str, target: usize) -> String {
    let mut acc = 0usize;
    let mut out = String::new();
    for (i, l) in content.split_inclusive('\n').enumerate() {
        out.push_str(l);
        acc += l.chars().count();
        if acc >= target { break; }
        let _ = i;
    }
    out
}

fn in_range(len: usize, d: Difficulty) -> bool {
    match d {
        Difficulty::Easy => len > 30 && len <= 119,
        Difficulty::Normal => len > 90 && len <= 219,
        Difficulty::Hard => len > 190 && len <= 519,
        _ => true,
    }
}

pub fn generate(chunks: &[crate::extract::Chunk]) -> Vec<Challenge> {
    let mut out: Vec<Challenge> = Vec::new();
    for c in chunks {
        let len = c.content.chars().count();
        let cls = comment_lines_of(&c.content, &c.language);
        let mut push = |content: String, sl: usize, d: Difficulty, out: &mut Vec<Challenge>| {
            let el = sl + content.split('\n').count().saturating_sub(1) - if content.ends_with('\n') { 0 } else { 0 };
            let el = sl + content.split_inclusive('\n').count().saturating_sub(1);
            let id = uuid::Uuid::new_v4().to_string();
            out.push(Challenge { id, file_path: c.file.clone(), start_line: sl, end_line: el, language: c.language.clone(), content, comment_lines: cls.clone(), difficulty: d });
        };
        // full chunk challenges
        push(c.content.clone(), c.start_line, Difficulty::Wild, &mut out);
        if c.is_file { push(c.content.clone(), c.start_line, Difficulty::Zen, &mut out); }
        for d in [Difficulty::Easy, Difficulty::Normal, Difficulty::Hard] {
            let t = d.target();
            if in_range(len, d) {
                if len <= t { push(c.content.clone(), c.start_line, d, &mut out); }
                else {
                    let tr = truncate_lines(&c.content, t);
                    if in_range(tr.chars().count(), d) { push(tr, c.start_line, d, &mut out); }
                }
            }
        }
    }
    // dedup by (difficulty, content)
    let mut seen = std::collections::HashSet::new();
    out.retain(|c| seen.insert((c.difficulty as u8, c.content.clone(), c.file_path.clone())));
    out
}

pub fn cache_dir() -> Option<std::path::PathBuf> {
    dirs::home_dir().map(|h| h.join(".gittype").join("cache"))
}

pub fn cache_key(repo_prefix: &str, commit: &str) -> String {
    format!("{}:{}", repo_prefix, commit)
}

pub fn cache_path(key: &str) -> Option<std::path::PathBuf> {
    let mut h = Sha256::new();
    h.update(key.as_bytes());
    let digest = h.finalize();
    cache_dir().map(|d| d.join(format!("{:x}.bin", digest)))
}

fn put_str(out: &mut Vec<u8>, s: &str) { out.push(s.len() as u8); out.extend_from_slice(s.as_bytes()); }
fn put_var(out: &mut Vec<u8>, mut v: u64) {
    if v <= 250 { out.push(v as u8); return; }
    let mut bytes = Vec::new();
    while v > 0 { bytes.push((v & 0xff) as u8); v >>= 8; }
    let tag = 0xfb + (bytes.len() as u8 - 2);
    out.push(tag);
    out.extend_from_slice(&bytes);
}

pub fn save_cache(key: &str, commit: &str, repo_prefix: &str, list: &[Challenge]) -> Option<std::path::PathBuf> {
    let path = cache_path(key)?;
    let mut raw: Vec<u8> = Vec::new();
    put_str(&mut raw, repo_prefix);
    put_str(&mut raw, commit);
    put_var(&mut raw, list.len() as u64);
    for c in list {
        put_str(&mut raw, &c.id);
        raw.push(1); put_str(&mut raw, &c.file_path);
        raw.push(1); put_var(&mut raw, c.start_line as u64);
        raw.push(1); put_var(&mut raw, c.end_line as u64);
        raw.push(1); put_str(&mut raw, &c.language);
        if c.comment_lines.is_empty() { raw.push(0); } else { raw.push(1); put_var(&mut raw, c.comment_lines.len() as u64); for l in &c.comment_lines { put_var(&mut raw, *l as u64); put_var(&mut raw, *l as u64); } }
        raw.push(1); put_var(&mut raw, c.difficulty as u8 as u64);
    }
    let mut enc = flate2::write::GzEncoder::new(Vec::new(), flate2::Compression::default());
    use std::io::Write;
    let _ = enc.write_all(&raw);
    let data = enc.finish().ok()?;
    let _ = std::fs::create_dir_all(path.parent()?);
    std::fs::write(&path, data).ok()?;
    Some(path)
}

#[derive(Debug, Clone)]
pub struct CachedEntry { pub id: String, pub file: String, pub start: usize, pub end: usize, pub lang: String, pub difficulty: Difficulty }

pub fn load_cache(key: &str, commit: &str) -> Option<Vec<CachedEntry>> {
    let path = cache_path(key)?;
    let data = std::fs::read(path).ok()?;
    let mut dec = flate2::read::GzDecoder::new(&data[..]);
    use std::io::Read;
    let mut raw = Vec::new();
    dec.read_to_end(&mut raw).ok()?;
    let mut p = 0usize;
    let rs = |raw: &Vec<u8>, p: &mut usize| -> Option<String> { let n = *raw.get(*p)? as usize; *p += 1; let s = String::from_utf8(raw.get(*p..*p+n)?.to_vec()).ok()?; *p += n; Some(s) };
    let gv = |raw: &Vec<u8>, p: &mut usize| -> Option<u64> {
        let t = *raw.get(*p)?; *p += 1;
        if t <= 250 { return Some(t as u64); }
        let n = match t { 0xfb => 2, 0xfc => 3, 0xfd => 4, _ => return None };
        if *p + n > raw.len() { return None; }
        let mut v = 0u64;
        for i in 0..n { v |= (raw[*p + i] as u64) << (8 * i); }
        *p += n;
        Some(v)
    };
    let _repo = rs(&raw, &mut p)?;
    let _commit = rs(&raw, &mut p)?;
    let cnt = gv(&raw, &mut p)? as usize;
    let mut out = Vec::new();
    for _ in 0..cnt {
        let id = rs(&raw, &mut p)?;
        if raw.get(p) != Some(&1) { break; } p += 1;
        let file = rs(&raw, &mut p)?;
        if raw.get(p) != Some(&1) { break; } p += 1;
        let start = gv(&raw, &mut p)? as usize;
        if raw.get(p) != Some(&1) { break; } p += 1;
        let end = gv(&raw, &mut p)? as usize;
        if raw.get(p) != Some(&1) { break; } p += 1;
        let lang = rs(&raw, &mut p)?;
        if raw.get(p) == Some(&1) { p += 1; let n = gv(&raw, &mut p)? as usize; p += n * 2; }
        else if raw.get(p) == Some(&0) { p += 1; } else { break; }
        if raw.get(p) != Some(&1) { break; } p += 1;
        let d = gv(&raw, &mut p)? as u8;
        let difficulty = match d { 0 => Difficulty::Easy, 1 => Difficulty::Normal, 2 => Difficulty::Hard, 3 => Difficulty::Wild, 4 => Difficulty::Zen, _ => Difficulty::Wild };
        out.push(CachedEntry { id, file, start, end, lang, difficulty });
    }
    Some(out)
}

pub fn cache_stats() -> (usize, u64) {
    let mut count = 0usize;
    let mut size = 0u64;
    if let Some(dir) = cache_dir() {
        if let Ok(rd) = std::fs::read_dir(&dir) {
            for e in rd.filter_map(|e| e.ok()) {
                if e.path().extension().map(|x| x == "bin").unwrap_or(false) {
                    count += 1;
                    if let Ok(m) = e.metadata() { size += m.len(); }
                }
            }
        }
    }
    (count, size)
}

pub fn cache_keys() -> Vec<String> {
    let mut out = Vec::new();
    if let Some(dir) = cache_dir() {
        if let Ok(rd) = std::fs::read_dir(&dir) {
            for e in rd.filter_map(|e| e.ok()) {
                if e.path().extension().map(|x| x == "bin").unwrap_or(false) {
                    if let Ok(data) = std::fs::read(e.path()) {
                        let mut dec = flate2::read::GzDecoder::new(&data[..]);
                        use std::io::Read;
                        let mut raw = Vec::new();
                        if dec.read_to_end(&mut raw).is_ok() && raw.len() > 1 {
                            let n = raw[0] as usize;
                            if raw.len() > 1 + n { out.push(String::from_utf8_lossy(&raw[1..1+n]).to_string()); }
                        }
                    }
                }
            }
        }
    }
    out.sort();
    out
}

pub fn clear_cache() -> usize {
    let mut n = 0;
    if let Some(dir) = cache_dir() {
        if let Ok(rd) = std::fs::read_dir(&dir) {
            for e in rd.filter_map(|e| e.ok()) {
                if e.path().extension().map(|x| x == "bin").unwrap_or(false) {
                    if std::fs::remove_file(e.path()).is_ok() { n += 1; }
                }
            }
        }
    }
    n
}

pub fn format_size(bytes: u64) -> String {
    if bytes < 1024 { format!("{} bytes", bytes) }
    else if bytes < 1024 * 1024 { format!("{:.1} KB", bytes as f64 / 1024.0) }
    else if bytes < 1024 * 1024 * 1024 { format!("{:.1} MB", bytes as f64 / (1024.0 * 1024.0)) }
    else { format!("{:.1} GB", bytes as f64 / (1024.0 * 1024.0 * 1024.0)) }
}
