// ------------------------------------------------------------- typing screen
pub struct TypingState {
    pub challenge: Challenge,
    pub started: bool,
    pub position: usize,
    pub keystrokes: usize,
    pub mistakes: usize,
    pub streak: usize,
    pub stage: usize,
    pub total_stages: usize,
    pub skips: usize,
    pub started_at: Option<std::time::Instant>,
}

pub fn render_typing(f: &mut Frame, area: Rect, st: &TypingState, colors: &ThemeColors) {
    let rows = Layout::vertical([
        Constraint::Length(1), Constraint::Length(3), Constraint::Min(3),
        Constraint::Length(3), Constraint::Length(3), Constraint::Length(1),
    ]).split(area);
    // challenge header
    let b = block_styled(colors, "Challenge", colors.success());
    let inner = b.inner(rows[1]);
    f.render_widget(b, rows[1]);
    let header = format!(" [{}] {}:{}-{} [{}] [{}]", crate::git_repo_label(st), st.challenge.file_path, st.challenge.start_line, st.challenge.end_line, st.challenge.lang_display(), st.challenge.difficulty.name());
    f.buffer_mut()[(inner.x, inner.y)].set_symbol(header).set_style(Style::new().fg(colors.title()).bg(colors.background()));
    // code box
    let cb = block_styled(colors, "Code", colors.success());
    let code_inner = cb.inner(rows[2]);
    f.render_widget(cb, rows[2]);
    render_code(f, code_inner, st, colors);
    // metrics
    let mb = block_styled(colors, "Metrics", colors.status_info());
    let mi = mb.inner(rows[3]);
    f.render_widget(mb, rows[3]);
    let secs = st.started_at.map(|t| t.elapsed().as_secs()).unwrap_or(0);
    let (wpm, cpm) = compute_speed(st, secs);
    let acc = if st.keystrokes > 0 { (st.keystrokes - st.mistakes) as f64 * 100.0 / st.keystrokes as f64 } else { 0.0 };
    let metrics = format!(" WPM: {} | CPM: {} | Accuracy: {}% | Mistakes: {} | Streak: {} | Time: {}s | Skips: {}", wpm, cpm, acc as u64, st.mistakes, st.streak, secs, st.skips);
    f.buffer_mut()[(mi.x, mi.y)].set_symbol(metrics).set_style(Style::new().fg(colors.cpm_wpm()).bg(colors.background()));
    // progress
    let pb = block_styled(colors, "Progress", colors.status_info());
    let pi = pb.inner(rows[4]);
    f.render_widget(pb, rows[4]);
    let total = st.challenge.content.chars().count().max(1);
    let pct = (st.position as f64 / total as f64 * 100.0).min(100.0);
    let g = Gauge::default().ratio((pct / 100.0).clamp(0.0, 1.0)).gauge_style(Style::new().fg(colors.success()).bg(colors.background()));
    f.render_widget(g, pi);
    // footer
    let y = rows[5].y;
    f.buffer_mut()[(rows[5].x, y)].set_symbol("[ESC] Options".to_string()).set_style(Style::new().fg(colors.key_back()).bg(colors.background()));
}

fn crate::git_repo_label(_st: &TypingState) -> String { String::new() }

fn compute_speed(st: &TypingState, secs: u64) -> (u64, u64) {
    if st.keystrokes == 0 || secs == 0 { return (0, 0); }
    let mins = secs as f64 / 60.0;
    let cpm = st.keystrokes as f64 / mins;
    ((cpm / 5.0).round() as u64, cpm.round() as u64)
}

pub fn render_code(f: &mut Frame, area: Rect, st: &TypingState, colors: &ThemeColors) {
    if !st.started {
        let msg = "Press [SPACE] to start";
        let x = area.x + center_x(area.width, msg);
        let y = area.y + area.height / 2;
        f.buffer_mut()[(x as u32, y as u32)].set_symbol(msg).set_style(Style::new().fg(colors.key_action()).bg(colors.background()));
        return;
    }
    let lines: Vec<&str> = st.challenge.content.split('\n').collect();
    let nlines = lines.len();
    let mut y = area.y;
    let mut row = 0usize;
    let prefix_w = 4usize;
    for (i, l) in lines.iter().enumerate() {
        if i >= area.height as usize { break; }
        let last = i + 1 == nlines;
        let show_nl = !last;
        let line_no = st.challenge.start_line + i;
        let prefix = format!("{:>width$} \u{2502} ", line_no, width = prefix_w);
        let _ = row;
        let text = if show_nl { format!("{}\u{21B5}", l) } else { l.to_string() };
        // render prefix
        let mut x = area.x;
        for (ci, c) in prefix.chars().enumerate() {
            if ci >= area.width as usize { break; }
            let style = if st.challenge.comment_lines.contains(&(i + 1)) {
                Style::new().fg(colors.text_secondary()).bg(colors.background())
            } else { Style::new().fg(colors.text_secondary()).bg(colors.background()) };
            f.buffer_mut()[(x as u32, y as u32)].set_symbol(c.to_string()).set_style(style);
            x += 1;
        }
        // render code with typed/untyped/cursor split
        render_line_spans(f, Rect::new(x, y, area.width.saturating_sub(prefix_w as u16 + 3), 1), &text, st, i, colors);
        y += 1;
        row += 1;
    }
}

fn render_line_spans(f: &mut Frame, area: Rect, text: &str, st: &TypingState, line_idx: usize, colors: &ThemeColors) {
    let _ = area;
    // compute the absolute index of this line's start within the content
    let start = st.challenge.content.split('\n').take(line_idx).map(|l| l.chars().count() + 1).sum::<usize>();
    let chars: Vec<char> = text.chars().collect();
    let mut x = area.x;
    for (i, c) in chars.iter().enumerate() {
        if x >= area.x + area.width { break; }
        let abs = start + i;
        let typed_len = st.position.min(st.challenge.content.chars().count());
        let style = if abs < typed_len {
            Style::new().fg(colors.typed()).bg(colors.background())
        } else if abs == typed_len {
            Style::new().fg(colors.cursor_fg()).bg(colors.cursor_bg())
        } else {
            Style::new().fg(colors.untyped()).bg(colors.background())
        };
        f.buffer_mut()[(x as u32, area.y as u32)].set_symbol(c.to_string()).set_style(style);
        x += 1;
    }
}

// -------------------------------------------------------------- result screens
pub fn render_stage_complete(f: &mut Frame, area: Rect, st: &TypingState, score: f64, colors: &ThemeColors) {
    let mut lines: Vec<(String, Style)> = Vec::new();
    lines.push((format!("=== STAGE {} COMPLETE ===", st.stage), Style::new().fg(colors.success()).add_modifier(Modifier::BOLD)));
    lines.push((String::new(), Style::new()));
    lines.push(("SCORE".to_string(), Style::new().fg(colors.score()).add_modifier(Modifier::BOLD)));
    for l in crate::art::digits(score as u64) { lines.push((l, Style::new().fg(colors.score()))); }
    lines.push((String::new(), Style::new()));
    let secs = st.started_at.map(|t| t.elapsed().as_secs_f64()).unwrap_or(0.0);
    let cpm = if secs > 0.0 { st.keystrokes as f64 / (secs / 60.0) } else { 0.0 };
    let acc = if st.keystrokes > 0 { (st.keystrokes - st.mistakes) as f64 * 100.0 / st.keystrokes as f64 } else { 0.0 };
    lines.push((format!("CPM: {} | WPM: {} | Time: {:.1}s", cpm as u64, (cpm / 5.0) as u64, secs), Style::new().fg(colors.cpm_wpm())));
    lines.push((format!("Keystrokes: {} | Mistakes: {} | Accuracy: {:.1}%", st.keystrokes, st.mistakes, acc), Style::new().fg(colors.accuracy())));
    lines.push((String::new(), Style::new()));
    lines.push((format!("Stage {} of {}", st.stage, st.total_stages), Style::new().fg(colors.stage_info())));
    lines.push(("Next stage starting...".to_string(), Style::new().fg(colors.stage_info())));
    lines.push((String::new(), Style::new()));
    lines.push(("[SPACE] Continue  [ESC] Quit".to_string(), Style::new().fg(colors.key_action())));
    draw_centered_lines(f, area, &lines, colors);
}

pub fn draw_centered_lines(f: &mut Frame, area: Rect, lines: &[(String, Style)], _colors: &ThemeColors) {
    let n = lines.len();
    let top = (area.height as usize).saturating_sub(n) / 2;
    for (i, (s, st)) in lines.iter().enumerate() {
        let y = area.y + top as u16 + i as u16;
        let lw = s.chars().count() as u16;
        let x = area.x + (area.width / 2).saturating_sub(lw / 2);
        f.buffer_mut()[(x as u32, y as u32)].set_symbol(s.clone()).set_style(*st);
    }
}
