pub fn render_stage_complete(f: &mut Frame, area: Rect, st: &TypingState, score: f64, colors: &ThemeColors) {
    let mut lines: Vec<(String, Style)> = Vec::new();
    lines.push((format!("=== STAGE {} COMPLETE ===", st.stage), Style::new().fg(colors.success()).add_modifier(Modifier::BOLD)));
    lines.push((String::new(), Style::new()));
    lines.push(("SCORE".to_string(), Style::new().fg(colors.score()).add_modifier(Modifier::BOLD)));
    for l in crate::art::digits(score as u64) { lines.push((l, Style::new().fg(colors.score()))); }
    lines.push((String::new(), Style::new()));
    let secs = st.started_at.map(|t| t.elapsed().as_secs_f64()).unwrap_or(0.0);
    let cpm = if secs > 0.0 { st.keystrokes as f64 / (secs / 60.0) } else { 0.0 };
    let acc = if st.keystrokes > 0 { (st.keystrokes - st.mistakes) as f64 * 100.0 / st.keystrokes as f64 } else { 0.0 };
    lines.push((format!("CPM: {} | WPM: {} | Time: {:.1}s", cpm as u64, (cpm / 5.0) as u64, secs), Style::new().fg(colors.cpm_wpm())));
    lines.push((format!("Keystrokes: {} | Mistakes: {} | Accuracy: {:.1}%", st.keystrokes, st.mistakes, acc), Style::new().fg(colors.accuracy())));
    lines.push((String::new(), Style::new()));
    lines.push((format!("Stage {} of {}", st.stage, st.total_stages), Style::new().fg(colors.stage_info())));
    lines.push(("Next stage starting...".to_string(), Style::new().fg(colors.stage_info())));
    lines.push((String::new(), Style::new()));
    lines.push(("[SPACE] Continue  [ESC] Quit".to_string(), Style::new().fg(colors.key_action())));
    draw_centered_lines(f, area, &lines, colors);
}

pub fn draw_centered_lines(f: &mut Frame, area: Rect, lines: &[(String, Style)], _colors: &ThemeColors) {
    let n = lines.len();
    let top = (area.height as usize).saturating_sub(n) / 2;
    for (i, (s, st)) in lines.iter().enumerate() {
        let y = area.y + top as u16 + i as u16;
        let lw = s.chars().count() as u16;
        let x = area.x + (area.width / 2).saturating_sub(lw / 2);
        f.buffer_mut()[(x as u32, y as u32)].set_symbol(s.clone()).set_style(*st);
    }
}
