pub fn render_help(f: &mut ratatui::Frame, area: Rect, tab: usize, scroll: usize, colors: &ThemeColors) {
    let b = block_styled(colors, "Help", colors.title());
    let inner = b.inner(area);
    f.render_widget(b, area);
    let tabbar = crate::rank::HELP_TABS.iter().enumerate().map(|(i, t)| if i == tab { format!("{} ", t) } else { format!("{} ", t) }).collect::<Vec<_>>().join("\u{2502} ");
    put(f, inner.x, inner.y, &format!(" {}", tabbar), Style::new().fg(colors.text()));
    // content
    let content = match tab {
        0 => crate::rank::HELP_CLI.to_string(),
        1 => crate::rank::HELP_SCORING.to_string(),
        2 => crate::rank::help_rank_system(),
        3 => crate::rank::HELP_GAME.to_string(),
        4 => crate::rank::HELP_COMMUNITY.to_string(),
        5 => crate::rank::HELP_ABOUT.to_string(),
        _ => crate::rank::THIRD_PARTY.lines().map(|l| format!("  {}", l.trim())).collect::<Vec<_>>().join("\n"),
    };
    let body_area = Rect::new(inner.x, inner.y + 1, inner.width, inner.height.saturating_sub(1));
    let p = Paragraph::new(content).wrap(Wrap { trim: false }).scroll((scroll as u16, 0));
    f.render_widget(p, body_area);
}

pub fn render_box_lines(f: &mut ratatui::Frame, area: Rect, title: &str, color: Color, colors: &ThemeColors, lines: &[(String, Style)], scroll: usize) {
    let b = block_styled(colors, title, color);
    let inner = b.inner(area);
    f.render_widget(b, area);
    for (i, (s, st)) in lines.iter().skip(scroll).enumerate() {
        if i >= inner.height as usize { break; }
        let x = inner.x + center_x(inner.width, s);
        put(f, x, inner.y + i as u16, s, *st);
    }
}

pub fn render_stage_complete(f: &mut ratatui::Frame, area: Rect, stage: usize, total: usize, score: f64, cpm: f64, secs: f64, keys: usize, mistakes: usize, acc: f64, colors: &ThemeColors, skipped: bool) {
