pub fn render_session_summary(f: &mut ratatui::Frame, area: Rect, data: &SessionSummaryData, colors: &ThemeColors) {
    let mut lines: Vec<(String, Style)> = Vec::new();
    lines.push(("=== SESSION COMPLETE ===".to_string(), Style::new().fg(colors.success()).add_modifier(Modifier::BOLD)));
    lines.push((String::new(), Style::new()));
    lines.push(("YOU'RE:".to_string(), Style::new().fg(colors.score()).add_modifier(Modifier::BOLD)));
    for l in crate::art::AWESOME { lines.push((l.to_string(), Style::new().fg(colors.score()))); }
    lines.push((String::new(), Style::new()));
    lines.push((data.tier_line.clone(), Style::new().fg(colors.stage_info())));
    lines.push((String::new(), Style::new()));
    lines.push(("SESSION SCORE".to_string(), Style::new().fg(colors.score()).add_modifier(Modifier::BOLD)));
    if data.is_best { lines.push(("*** TODAY'S BEST ***".to_string(), Style::new().fg(colors.warning()).add_modifier(Modifier::BOLD))); }
    for l in crate::art::digits(data.score.max(0.0) as u64) { lines.push((l, Style::new().fg(colors.score()))); }
    lines.push((format!("({}{})", if data.delta >= 0.0 { "+" } else { "" }, data.delta as i64), Style::new().fg(if data.delta >= 0.0 { colors.success() } else { colors.error() })));
    lines.push((format!("CPM: {} | WPM: {} | Time: {:.1}s", data.cpm as u64, (data.cpm / 5.0) as u64, data.secs), Style::new().fg(colors.cpm_wpm())));
    lines.push((format!("Keystrokes: {} | Mistakes: {} | Accuracy: {:.1}%", data.keys, data.mistakes, data.acc), Style::new().fg(colors.accuracy())));
