pub fn center_x(w: u16, s: &str) -> u16 {
    let lw = s.chars().count() as u16;
    (w / 2).saturating_sub(lw / 2)
}

pub fn put(f: &mut ratatui::Frame, x: u16, y: u16, s: &str, st: Style) {
    if y >= f.area().height { return; }
    let mut cx = x;
    for c in s.chars() {
        if cx >= f.area().width { break; }
        f.buffer_mut()[(cx as u32, y as u32)].set_symbol(c.to_string()).set_style(st);
        cx += 1;
    }
}

pub fn block_styled(colors: &ThemeColors, title: &str, color: Color) -> Block<'static> {
    Block::bordered().border_type(BorderType::Plain)
        .border_style(Style::new().fg(colors.border()))
        .title(ratatui::text::Span::styled(title.to_string(), Style::new().fg(color).bg(colors.background())))
        .style(Style::new().bg(colors.background()))
}

pub fn draw_centered_lines(f: &mut ratatui::Frame, area: Rect, lines: &[(String, Style)]) {
    let n = lines.len();
    if n == 0 { return; }
    let top = (area.height as usize).saturating_sub(n) / 2;
    for (i, (s, st)) in lines.iter().enumerate() {
        let y = area.y + top as u16 + i as u16;
        let x = area.x + center_x(area.width, s);
        put(f, x, y, s, *st);
    }
}

