pub fn render_title(f: &mut ratatui::Frame, area: Rect, data: &TitleData, diff: usize, colors: &ThemeColors) {
    let lines = title_lines(data, diff, colors);
    let n = lines.len();
    let avail = area.height.saturating_sub(1) as usize;
    let top = avail.saturating_sub(n) / 2;
    for (i, (s, st)) in lines.iter().enumerate() {
        let y = area.y + top as u16 + i as u16;
        if y >= area.y + avail as u16 { break; }
        let x = area.x + center_x(area.width, s);
        put(f, x, y, s, *st);
    }
    if let Some(r) = &data.repo {
        let dirty = if r.dirty { "\u{2717}" } else { "\u{2713}" };
        let commit = r.commit.as_deref().map(|c| c.chars().take(8).collect::<String>()).unwrap_or_default();
        let branch = r.branch.clone().unwrap_or_default();
        let footer = format!("\u{1F4C1} {} \u{2022} \u{1F33F} {} \u{2022} \u{1F4DD} {} \u{2022} {}", r.display_name(), branch, commit, dirty);
        let y = area.y + area.height - 1;
        let x = area.x + center_x(area.width, &footer);
        put(f, x, y, &footer, Style::new().fg(colors.text_secondary()));
    }
}

