use std::io::Write;
use std::time::{Duration, Instant};
use ratatui::layout::{Constraint, Layout, Rect};
use ratatui::style::{Modifier, Style};
use crate::challenge::{Challenge, Difficulty};
use crate::theme::ThemeColors;
