const STAGE_ANIM: f64 = 2.25;

pub fn run(mut app: App, challenges: Vec<Challenge>) -> crate::error::AppResult<()> {
    let mut stdout = std::io::stdout();
    ct::EnterAlternateScreen;
    crossterm::execute!(stdout, ct::EnterAlternateScreen, ct::EnableMouseCapture).ok();
    ct::enable_raw_mode().ok();
    let mut terminal = match ratatui::init() {
        t => t,
    };
    let res = event_loop(&mut terminal, &mut app, challenges);
    let _ = ratatui::restore();
    ct::disable_raw_mode().ok();
    crossterm::execute!(std::io::stdout(), ct::LeaveAlternateScreen, ct::DisableMouseCapture).ok();
    res
}

fn event_loop(terminal: &mut ratatui::DefaultTerminal, app: &mut App, challenges: Vec<Challenge>) -> crate::error::AppResult<()> {
    let mut all = challenges;
    let mut stage_challenges: Vec<Challenge> = Vec::new();
    let mut pending_result: Option<StageResult> = None;
    loop {
        // animations / timers
        if app.screen == Screen::Loading {
            let now = Instant::now();
            if now.duration_since(app.last_anim) >= Duration::from_millis(600) {
                app.last_anim = now;
                app.loading_anim = (app.loading_anim + 1) % crate::app::LOAD_ART.len();
                app.loading_step += 1;
            }
        }
        if app.screen == Screen::Typing {
            if let Some(t) = &mut app.typing {
                if !t.started {
                    if let Some(s) = app.input_start {
                        if s.elapsed() >= Duration::from_millis((STAGE_ANIM * 1000.0) as u64) {
                            t.started = true;
                        }
                    }
                }
            }
        }
        terminal.draw(|f| render(f, app))?;
        // input
        let timeout = if app.screen == Screen::Loading { Duration::from_millis(50) } else { Duration::from_millis(50) };
        if crossterm::event::poll(timeout).ok() == Some(true) {
            if let Ok(ev) = crossterm::event::read() {
                match ev {
                    Event::Key(k) => {
                        if k.kind == crossterm::event::KeyEventKind::Press {
                            let action = handle_key(app, k, &mut all, &mut stage_challenges, &mut pending_result);
                            match action {
                                Flow::Continue => {}
                                Flow::Quit => return Ok(()),
                                Flow::SetChallenges(v) => { all = v; }
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
        if app.screen == Screen::Quit { return Ok(()); }
    }
}

enum Flow { Continue, Quit, SetChallenges(Vec<Challenge>) }

fn handle_key(app: &mut App, k: KeyEvent, all: &mut Vec<Challenge>, stage_challenges: &mut Vec<Challenge>, pending: &mut Option<StageResult>) -> Flow {
    let colors = app.colors;
    match app.screen {
        Screen::Loading => { app.screen = Screen::Title; Flow::Continue }
        Screen::Title => {
            match k.code {
                KeyCode::Right | KeyCode::Char('l') => { app.diff = (app.diff + 1) % 5; Flow::Continue }
                KeyCode::Left | KeyCode::Char('h') => { app.diff = (app.diff + 4) % 5; Flow::Continue }
                KeyCode::Char('r') | KeyCode::Char('R') => { app.screen = Screen::Records; Flow::Continue }
                KeyCode::Char('a') | KeyCode::Char('A') => { app.screen = Screen::Analytics; Flow::Continue }
                KeyCode::Char('s') | KeyCode::Char('S') => { app.screen = Screen::Settings; Flow::Continue }
                KeyCode::Char('i') | KeyCode::Char('?') | KeyCode::Char('I') => { app.screen = Screen::Help; Flow::Continue }
                KeyCode::Esc => { app.screen = Screen::TotalSummary; Flow::Continue }
                KeyCode::Char(' ') => { start_session(app, all, stage_challenges); Flow::Continue }
                _ => Flow::Continue,
            }
        }
        Screen::Help => {
            match k.code {
                KeyCode::Right | KeyCode::Char('l') => { app.help_tab = (app.help_tab + 1) % 7; app.help_scroll = 0; Flow::Continue }
                KeyCode::Left | KeyCode::Char('h') => { app.help_tab = (app.help_tab + 6) % 7; app.help_scroll = 0; Flow::Continue }
                KeyCode::Down | KeyCode::Char('j') => { app.help_scroll += 1; Flow::Continue }
                KeyCode::Up | KeyCode::Char('k') => { app.help_scroll = app.help_scroll.saturating_sub(1); Flow::Continue }
                KeyCode::Esc | KeyCode::Char('q') => { app.screen = Screen::Title; Flow::Continue }
                _ => Flow::Continue,
            }
        }
        Screen::Records => {
            match k.code { KeyCode::Esc => { app.screen = Screen::Title; Flow::Continue }, _ => Flow::Continue }
        }
        Screen::Analytics => {
            match k.code { KeyCode::Esc => { app.screen = Screen::Title; Flow::Continue }, _ => Flow::Continue }
        }
        Screen::Settings => {
            match k.code { KeyCode::Esc => { app.screen = Screen::Title; Flow::Continue }, _ => Flow::Continue }
        }
        Screen::Typing => {
            if let Some(t) = &mut app.typing {
                if !t.started {
                    if k.code == KeyCode::Char(' ') {
                        app.input_start = Some(Instant::now());
                    }
                    return Flow::Continue;
                }
                match k.code {
                    KeyCode::Esc => { app.screen = Screen::Options; Flow::Continue }
                    KeyCode::Char(c) => {
                        if c == 'S' { return Flow::Continue; }
                        type_char(t, c);
                        if t.position >= t.challenge.content.chars().count() {
                            complete_stage(app, t, pending);
                        }
                        Flow::Continue
                    }
                    KeyCode::Enter => { type_newline(t); if t.position >= t.challenge.content.chars().count() { complete_stage(app, t, pending); } Flow::Continue }
                    KeyCode::Backspace => Flow::Continue,
                    _ => Flow::Continue,
                }
            } else { Flow::Continue }
        }
        Screen::Options => {
            match k.code {
                KeyCode::Char('s') | KeyCode::Char('S') => {
                    if let Some(t) = &mut app.typing {
                        t.skips_used += 1;
                        skip_stage(app, t, pending);
                    }
                    Flow::Continue
                }
                KeyCode::Char('q') | KeyCode::Char('Q') => { app.screen = Screen::SessionFailed; Flow::Continue }
                KeyCode::Esc => { app.screen = Screen::Typing; Flow::Continue }
                _ => Flow::Continue,
            }
        }
        Screen::StageResult => {
            match k.code {
                KeyCode::Char(' ') => { next_stage(app, stage_challenges); Flow::Continue }
                KeyCode::Esc => { app.screen = Screen::SessionFailed; Flow::Continue }
                _ => Flow::Continue,
            }
        }
        Screen::SessionSummary => {
            match k.code {
                KeyCode::Char('d') | KeyCode::Char('D') => { app.screen = Screen::Details; Flow::Continue }
                KeyCode::Char('s') | KeyCode::Char('S') => { app.screen = Screen::Share; Flow::Continue }
                KeyCode::Esc => { app.screen = Screen::TotalSummary; Flow::Continue }
                _ => Flow::Continue,
            }
        }
        Screen::SessionFailed => {
            match k.code {
                KeyCode::Esc => { app.screen = Screen::TotalSummary; Flow::Continue }
                _ => Flow::Continue,
            }
        }
        Screen::TotalSummary => {
            match k.code {
                KeyCode::Char('s') | KeyCode::Char('S') => { app.screen = Screen::Share; Flow::Continue }
                KeyCode::Esc => Flow::Quit,
                _ => Flow::Continue,
            }
        }
        Screen::Share => { match k.code { KeyCode::Esc => { app.screen = Screen::TotalSummary; Flow::Continue }, _ => Flow::Continue } }
        Screen::Details => { match k.code { KeyCode::Esc => { app.screen = Screen::SessionSummary; Flow::Continue }, _ => Flow::Continue } }
        _ => Flow::Continue,
    }
}

fn type_char(t: &mut TypingState, c: char) {
    let chars: Vec<char> = t.challenge.content.chars().collect();
    if t.position >= chars.len() { return; }
    t.keystrokes += 1;
    if chars[t.position] == c {
        t.position += 1;
        t.streak += 1;
        t.streaks.push(t.streak);
    } else {
        t.mistakes += 1;
        t.streak = 0;
        t.streaks.push(0);
    }
    if t.started_at.is_none() { t.started_at = Some(Instant::now()); }
}

fn type_newline(t: &mut TypingState) {
    let chars: Vec<char> = t.challenge.content.chars().collect();
    if t.position >= chars.len() { return; }
    t.keystrokes += 1;
    if chars[t.position] == '\n' {
        t.position += 1;
        // auto-indent: skip the leading whitespace of the next line
        while t.position < chars.len() && (chars[t.position] == ' ' || chars[t.position] == '\t') { t.position += 1; }
        // skip whole-line comments
        while let Some(p) = is_comment_at(t, t.position) { t.position = p; }
        t.streak += 1;
        t.streaks.push(t.streak);
    } else { t.mistakes += 1; t.streak = 0; t.streaks.push(0); }
    if t.started_at.is_none() { t.started_at = Some(Instant::now()); }
}

fn is_comment_at(t: &TypingState, pos: usize) -> Option<usize> {
    // if the current position is inside a comment-only line, skip to the next line's first non-ws char
    let before = t.challenge.content.chars().take(pos).collect::<String>();
    let line_start = before.rfind('\n').map(|i| i + 1).unwrap_or(0);
    let line_no = before.matches('\n').count() + 1;
    let chars: Vec<char> = t.challenge.content.chars().collect();
    let mut e = pos;
    while e < chars.len() && chars[e] != '\n' { e += 1; }
    let line: String = chars[line_start..e].iter().collect();
    if crate::challenge::comment_lines_of(&format!("{}\n", line), &t.challenge.language).contains(&1) && t.challenge.comment_lines.contains(&line_no) {
        // skip to next line, then the indentation
        let mut p = e + 1;
        while p < chars.len() && (chars[p] == ' ' || chars[p] == '\t') { p += 1; }
        return Some(p);
    }
    None
}

fn start_session(app: &mut App, all: &mut Vec<Challenge>, stage_challenges: &mut Vec<Challenge>) {
    let diff = Difficulty::ALL[app.diff];
    let pool: Vec<Challenge> = all.iter().filter(|c| c.difficulty == diff).cloned().collect();
    if pool.is_empty() { return; }
    let total = 3usize;
    let mut picks = Vec::new();
    let mut rng = fastrand(rng_seed());
    for _ in 0..total {
        let i = (rng() * pool.len() as f64) as usize % pool.len();
        picks.push(pool[i].clone());
    }
    *stage_challenges = picks;
    app.session = Some(Session { challenges: stage_challenges.clone(), repo: app.title.repo.clone(), stage: 1, total_stages: total, skips: 3, stage_results: Vec::new(), difficulty: diff });
    let c = stage_challenges[0].clone();
    app.typing = Some(TypingState { challenge: c, started: false, position: 0, keystrokes: 0, mistakes: 0, streak: 0, skips_used: 0, started_at: None, stage: 1, total_stages: total, skips: 3, streaks: Vec::new() });
    app.input_start = None;
    app.screen = Screen::Typing;
}

fn rng_seed() -> u64 {
    std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.subsec_nanos() as u64).unwrap_or(12345)
}

fn fastrand(seed: u64) -> impl FnMut() -> f64 {
    let mut x = seed | 1;
    move || {
        x ^= x << 13; x ^= x >> 7; x ^= x << 17;
        (x % 1_000_000) as f64 / 1_000_000.0
    }
}

fn complete_stage(app: &mut App, t: &mut TypingState, pending: &mut Option<StageResult>) {
    let secs = t.started_at.map(|s| s.elapsed().as_secs_f64()).unwrap_or(0.0);
    let cpm = if secs > 0.0 { t.keystrokes as f64 / (secs / 60.0) } else { 0.0 };
    let acc = if t.keystrokes > 0 { (t.keystrokes - t.mistakes) as f64 * 100.0 / t.keystrokes as f64 } else { 0.0 };
    let score = crate::score::score_of(cpm, acc, t.mistakes as f64);
    let (rank, tier, _tot) = crate::rank::rank_for(score);
    let r = StageResult {
        file: t.challenge.file_path.clone(), range: format!("{}:{}", t.challenge.file_path, t.challenge.start_line),
        score, cpm, wpm: cpm / 5.0, keys: t.keystrokes, mistakes: t.mistakes, acc, duration_ms: (secs * 1000.0) as u64,
        rank: rank.to_string(), tier: tier.to_string(), skipped: false,
    };
    *pending = Some(r);
    app.screen = Screen::StageResult;
}

fn skip_stage(app: &mut App, t: &mut TypingState, pending: &mut Option<StageResult>) {
    let secs = t.started_at.map(|s| s.elapsed().as_secs_f64()).unwrap_or(0.0);
    let cpm = if secs > 0.0 { t.keystrokes as f64 / (secs / 60.0) } else { 0.0 };
    let acc = if t.keystrokes > 0 { (t.keystrokes - t.mistakes) as f64 * 100.0 / t.keystrokes as f64 } else { 0.0 };
    let score = crate::score::score_of(cpm, acc, t.mistakes as f64);
    let (rank, tier, _t) = crate::rank::rank_for(score);
    let r = StageResult { file: t.challenge.file_path.clone(), range: format!("{}:{}", t.challenge.file_path, t.challenge.start_line), score, cpm, wpm: cpm/5.0, keys: t.keystrokes, mistakes: t.mistakes, acc, duration_ms: (secs*1000.0) as u64, rank: rank.to_string(), tier: tier.to_string(), skipped: true };
    *pending = Some(r);
    app.screen = Screen::StageResult;
}

fn next_stage(app: &mut App, stage_challenges: &mut Vec<Challenge>) {
    if let (Some(sess), Some(res)) = (app.session.as_mut(), pending_take()) {
        sess.stage_results.push(res);
    }
    let sess = match app.session.as_mut() { Some(s) => s, None => { app.screen = Screen::Title; return; } };
    if sess.stage >= sess.total_stages {
        finish_session(app);
        return;
    }
    sess.stage += 1;
    let c = stage_challenges.get(sess.stage - 1).cloned();
    if let Some(c) = c {
        app.typing = Some(TypingState { challenge: c, started: false, position: 0, keystrokes: 0, mistakes: 0, streak: 0, skips_used: 0, started_at: None, stage: sess.stage, total_stages: sess.total_stages, skips: sess.skips.saturating_sub(1), streaks: Vec::new() });
        app.input_start = None;
        app.screen = Screen::Typing;
    } else { finish_session(app); }
}

fn pending_take() -> Option<StageResult> { PENDING.lock().unwrap().take() }

static PENDING: std::sync::Mutex<Option<StageResult>> = std::sync::Mutex::new(None);

fn finish_session(app: &mut App) {
    let sess = match app.session.clone() { Some(s) => s, None => { app.screen = Screen::Title; return; } };
    let n = sess.stage_results.len().max(1) as f64;
    let score = sess.stage_results.iter().map(|r| r.score).sum::<f64>() / n;
    let cpm = sess.stage_results.iter().map(|r| r.cpm).sum::<f64>() / n;
    let keys = sess.stage_results.iter().map(|r| r.keys).sum();
    let mistakes = sess.stage_results.iter().map(|r| r.mistakes).sum();
    let secs = sess.stage_results.iter().map(|r| r.duration_ms).sum::<u64>() as f64 / 1000.0;
    let acc = if keys > 0 { (keys - mistakes) as f64 * 100.0 / keys as f64 } else { 0.0 };
    let (idx, rank, _t) = crate::rank::rank_for(score);
    let (first, cnt) = crate::rank::tier_range(crate::rank::RANKS.get(idx).map(|r| r.tier).unwrap_or("Beginner"));
    let tier_line = format!("{} tier - {}/{} (overall {}/{})", crate::rank::RANKS.get(idx).map(|r| r.tier).unwrap_or("Beginner"), idx - first + 1, cnt, idx + 1, crate::rank::RANKS.len());
    let delta = 0.0;
    app.summary = Some(SessionSummaryData { score, delta, cpm, secs, keys, mistakes, acc, tier_line, is_best: true });
    app.detail_lines = {
        let mut v = Vec::new();
        v.push(format!("  Today's Best: Score {} | CPM {:.1} | Acc {:.1}%", score as i64, cpm, acc));
        v.push(format!("   Weekly Best: Score {} | CPM {:.1} | Acc {:.1}%", score as i64, cpm, acc));
        v.push(format!(" All time Best: Score {} | CPM {:.1} | Acc {:.1}%", score as i64, cpm, acc));
        v.push(format!("Stage Results: [{}]", sess.repo.as_ref().map(|r| r.display_name()).unwrap_or_default()));
        for r in &sess.stage_results {
            v.push(String::new());
            v.push(format!("  {}", r.range));
            v.push(format!("   Score: {} | CPM: {:.1} | Acc: {:.1}%", r.score as i64, r.cpm, r.acc));
        }
        v
    };
    app.share_text = format!("Score: {}, CPM: {}, Keystrokes: {}, Time: {:.1}min", score as i64, cpm as i64, keys, secs / 60.0);
    app.screen = Screen::SessionSummary;
}

fn render(f: &mut ratatui::Frame, app: &App) {
    let area = f.area();
    let colors = &app.colors;
    match app.screen {
        Screen::Loading => {
            let art = crate::app::LOAD_ART[app.loading_anim % crate::app::LOAD_ART.len()];
            let b = block_styled(colors, "Loading", colors.status_info());
            let inner = b.inner(area);
            f.render_widget(b, area);
            for (i, l) in art.split('\n').enumerate() {
                let x = inner.x + center_x(inner.width, l);
                put(f, x, inner.y + 3 + i as u16, l, Style::new().fg(colors.stage_info()));
            }
        }
        Screen::Title => render_title(f, area, &app.title, app.diff, colors),
        Screen::Help => render_help(f, area, app.help_tab, app.help_scroll, colors),
        Screen::Typing => {
            if let Some(t) = &app.typing {
                let rows = Layout::vertical([Constraint::Length(1), Constraint::Length(3), Constraint::Min(3), Constraint::Length(3), Constraint::Length(3), Constraint::Length(1)]).split(area);
                // challenge box
                let b = block_styled(colors, "Challenge", colors.success());
                let inner = b.inner(rows[1]);
                f.render_widget(b, rows[1]);
                let repo_label = app.title.repo.as_ref().map(|r| r.display_name()).unwrap_or_default();
                let header = format!(" [{}] {}:{}-{} [{}] [{}]", repo_label, t.challenge.file_path, t.challenge.start_line, t.challenge.end_line, t.challenge.lang_display(), t.challenge.difficulty.name());
                f.buffer_mut()[(inner.x, inner.y)].set_symbol(header).set_style(Style::new().fg(colors.title()).bg(colors.background()));
                // code
                let cb = block_styled(colors, "Code", colors.success());
                let ci = cb.inner(rows[2]);
                f.render_widget(cb, rows[2]);
                render_code(f, ci, t, colors);
                // metrics
                let mb = block_styled(colors, "Metrics", colors.status_info());
                let mi = mb.inner(rows[3]);
                f.render_widget(mb, rows[3]);
                let secs = t.started_at.map(|s| s.elapsed().as_secs()).unwrap_or(0);
                let mins = secs as f64 / 60.0;
                let cpm = if mins > 0.0 { t.keystrokes as f64 / mins } else { 0.0 };
                let acc = if t.keystrokes > 0 { (t.keystrokes - t.mistakes) as f64 * 100.0 / t.keystrokes as f64 } else { 0.0 };
                let metrics = format!(" WPM: {} | CPM: {} | Accuracy: {}% | Mistakes: {} | Streak: {} | Time: {}s | Skips: {}", (cpm/5.0).round() as u64, cpm.round() as u64, acc as u64, t.mistakes, t.streak, secs, t.skips);
                f.buffer_mut()[(mi.x, mi.y)].set_symbol(metrics).set_style(Style::new().fg(colors.cpm_wpm()).bg(colors.background()));
                // progress
                let pb = block_styled(colors, "Progress", colors.status_info());
                let pi = pb.inner(rows[4]);
                f.render_widget(pb, rows[4]);
                let total = t.challenge.content.chars().count().max(1) as f64;
                let pct = ((t.keystrokes as f64 + 0.0) / total).clamp(0.0, 1.0);
                let g = Gauge::default().ratio(pct).gauge_style(Style::new().fg(colors.success()).bg(colors.background()));
                f.render_widget(g, pi);
                put(f, rows[5].x, rows[5].y, "[ESC] Options", Style::new().fg(colors.key_back()));
            }
        }
        Screen::Options => {
            if let Some(t) = &app.typing {
                render_typing_bg(f, area, t, colors);
            }
            let w = 50u16; let h = 10u16;
            let x = area.x + (area.width.saturating_sub(w)) / 2;
            let y = area.y + (area.height.saturating_sub(h)) / 2;
            let r = Rect::new(x, y, w.min(area.width), h.min(area.height));
            let b = block_styled(colors, "Game Options", colors.warning());
            let inner = b.inner(r);
            f.render_widget(b, r);
            let lines = ["", "Choose an option:", "", &format!("[S] Skip challenge ({})", app.typing.as_ref().map(|t| t.skips).unwrap_or(3)), "[Q] Quit (fail)", "[ESC] Back to game", ""];
            for (i, l) in lines.iter().enumerate() {
                let x = inner.x + center_x(inner.width, l);
                put(f, x, inner.y + i as u16, l, Style::new().fg(colors.text()));
            }
        }
        Screen::StageResult => {
            if let Some(t) = &app.typing {
                let skipped = false;
                let secs = t.started_at.map(|s| s.elapsed().as_secs_f64()).unwrap_or(0.0);
                let mins = secs / 60.0;
                let cpm = if mins > 0.0 { t.keystrokes as f64 / mins } else { 0.0 };
                let acc = if t.keystrokes > 0 { (t.keystrokes - t.mistakes) as f64 * 100.0 / t.keystrokes as f64 } else { 0.0 };
                let score = crate::score::score_of(cpm, acc, t.mistakes as f64);
                render_stage_complete(f, area, t.stage, t.total_stages, score, cpm, secs, t.keystrokes, t.mistakes, acc, colors, skipped);
            }
        }
        Screen::SessionSummary => { if let Some(s) = &app.summary { render_session_summary(f, area, s, colors); } }
        Screen::SessionFailed => {
            let (st, tot) = app.session.as_ref().map(|s| (s.stage, s.total_stages)).unwrap_or((0, 3));
            render_session_failed(f, area, st, tot, 0.0, 0.0, 0, 0, 0.0, colors);
        }
        Screen::TotalSummary => render_total_summary(f, area, &app.total, colors),
        Screen::Share => render_share(f, area, &app.share_text, colors),
        Screen::Details => render_details(f, area, &app.detail_lines, colors),
        Screen::Records => render_records(f, area, colors),
        Screen::Analytics => render_analytics(f, area, colors),
        Screen::Settings => render_settings(f, area, colors),
        Screen::RepoList => render_repo_list(f, area, colors),
        Screen::RepoPlay => render_repo_list(f, area, colors),
        Screen::TrendingLang => render_trending_lang(f, area, colors),
        Screen::TrendingRepos => render_trending_repos(f, area, colors),
        Screen::Quit => {}
    }
}

