fn render_code(f: &mut ratatui::Frame, area: Rect, t: &TypingState, colors: &ThemeColors) {
    if !t.started {
        let msg = "Press [SPACE] to start";
        let x = area.x + center_x(area.width, msg);
        let y = area.y + area.height / 2;
        put(f, x, y, msg, Style::new().fg(colors.key_action()));
        return;
    }
    let lines: Vec<&str> = t.challenge.content.split('\n').collect();
    let mut y = area.y;
    for (i, l) in lines.iter().enumerate() {
        if y >= area.y + area.height { break; }
        let last = i + 1 == lines.len();
        let line_no = t.challenge.start_line + i;
        let prefix = format!("{:>4} \u{2502} ", line_no);
        let mut x = area.x;
        for c in prefix.chars() {
            if x >= area.x + area.width { break; }
            f.buffer_mut()[(x as u32, y as u32)].set_symbol(c.to_string()).set_style(Style::new().fg(colors.text_secondary()).bg(colors.background()));
            x += 1;
        }
        let text = if last { l.to_string() } else { format!("{}\u{21B5}", l) };
        let chars: Vec<char> = text.chars().collect();
        let start = t.challenge.content.split('\n').take(i).map(|l| l.chars().count() + 1).sum::<usize>();
        let typed = t.position;
        for (j, c) in chars.iter().enumerate() {
            if x >= area.x + area.width { break; }
            let abs = start + j;
            let st = if abs < typed { Style::new().fg(colors.typed()).bg(colors.background()) }
                else if abs == typed { Style::new().fg(colors.cursor_fg()).bg(colors.cursor_bg()) }
                else { Style::new().fg(colors.untyped()).bg(colors.background()) };
            f.buffer_mut()[(x as u32, y as u32)].set_symbol(c.to_string()).set_style(st);
            x += 1;
        }
        y += 1;
    }
}
