pub fn score_of(cpm: f64, accuracy: f64, mistakes: f64) -> f64 {
    let base = cpm * (accuracy / 100.0) * 10.0;
    let consistency = if accuracy >= 100.0 { 0.7 * base } else { 0.35 * base };
    let time_bonus = 0.0;
    let penalty = mistakes * 5.0;
    (base + consistency + time_bonus - penalty) * 2.0 + 100.0
}
