fn ensure_terminal() -> Result<(), GitTypeError> {
    use std::io::IsTerminal;
    if !std::io::stdout().is_terminal() {
        return Err(GitTypeError::TerminalError("Not running in a terminal environment. Please run in a proper terminal.".into()));
    }
