        match std::fs::OpenOptions::new().read(true).write(true).open("/dev/tty") {
            Ok(_) => {}
            Err(e) => return Err(GitTypeError::TerminalError(format!("Failed to create terminal: {}", e))),
        }
    }
    Ok(())
}

fn run_game(args: &cli::Cli) -> Result<(), GitTypeError> {
    logging::info("gittype::presentation::cli::commands::game", "Starting GitType game session");
    // version check (no network available)
    logging::warn("gittype::domain::repositories::version_repository", "Failed to fetch latest version from API: Failed to extract code chunks: Failed to fetch release: error sending request for url (https://api.github.com/repos/unhappychoice/gittype/releases/latest)");
    logging::info("gittype::presentation::cli::commands::game", &format!("Initializing all screens with GameData parameters: repo_spec={:?}, repo_path={:?}", args.repo.clone(), args.repo_path.clone()));
    ensure_terminal()?;
    // resolve repository
    let root = git::resolve_root(args.repo_path.as_deref());
    if !git::is_git_repo(&root) {
        return Err(GitTypeError::ExtractionError("Git repository not found".into()));
    }
    let info = git::repo_info(&root);
    let langs = args.langs.as_deref().map(|s| s.split(',').map(|x| x.trim().to_string()).filter(|x| !x.is_empty()).collect::<Vec<_>>());
    let files = extract::collect_files(&root, langs.as_ref());
    if files.is_empty() {
        return Err(GitTypeError::ExtractionError("No supported files found in repository".into()));
    }
    let mut chunks = Vec::new();
    for (rel, lang) in &files {
        let content = match std::fs::read_to_string(root.join(rel)) { Ok(c) => c, Err(_) => continue };
        chunks.extend(extract::extract(rel, lang, &content));
    }
    let list = challenge::generate(&chunks);
    let commit = info.commit.clone().unwrap_or_default();
    let key = info.cache_key(&commit);
    let existing = challenge::load_cache(&key, &commit);
    let counts: [Option<usize>; 5];
    match existing {
        Some(entries) if !entries.is_empty() => {
            let mut c = [None; 5];
            for d in 0..5 { c[d] = Some(entries.iter().filter(|e| e.difficulty as usize == d).count()); }
            counts = c;
            // rebuild full challenges from the source files
            let mut by_diff: Vec<Vec<(String, usize, usize)>> = vec![Vec::new(); 5];
            for e in &entries { by_diff[e.difficulty as usize].push((e.file.clone(), e.start, e.end)); }
            let mut out = Vec::new();
            for (i, d) in challenge::Difficulty::ALL.iter().enumerate() {
                for (file, sl, el) in &by_diff[i] {
                    if let Some(content) = file_content(&root, file, *sl, *el) {
                        out.push(challenge::Challenge {
                            id: uuid::Uuid::new_v4().to_string(), file_path: file.clone(),
                            start_line: *sl, end_line: *el, language: lang_of(file).to_string(),
                            content, comment_lines: Vec::new(), difficulty: *d,
                        });
                    }
                }
            }
            logging::info("gittype::presentation::game::models::loading_steps::generating_step", &format!("Using cached challenges for {}", info.remote_url.clone().unwrap_or_default()));
            logging::info("gittype::presentation::tui::screen_manager", "Initializing screen: Title");
            logging::info("gittype::presentation::game::stage_repository", "\u{2705} StageRepository: Title screen data ready (will be updated by ScreenManager)");
            let app = tui::App::new(theme::default_theme(), Some(info), counts);
            return tui::run(app, out);
        }
        _ => {}
    }
    counts = [None; 5];
    if list.is_empty() {
        return Err(GitTypeError::ExtractionError("No supported files found in repository".into()));
    }
    challenge::save_cache(&key, &commit, &info.cache_key_prefix(), &list);
    logging::info("gittype::presentation::game::models::loading_steps::generating_step", &format!("Successfully cached {} challenges for {}", list.len(), info.remote_url.clone().unwrap_or("file://local".into())));
    logging::info("gittype::presentation::tui::screen_manager", "Initializing screen: Title");
    logging::info("gittype::presentation::game::stage_repository", "\u{2705} StageRepository: Title screen data ready (will be updated by ScreenManager)");
    let mut c = [None; 5];
    for d in 0..5 { c[d] = Some(list.iter().filter(|x| x.difficulty as usize == d).count()); }
    let app = tui::App::new(theme::default_theme(), Some(info), c);
    tui::run(app, list)
}

fn lang_of(file: &str) -> &'static str { extract::lang_for_file(file).unwrap_or("rust") }

fn file_content(root: &std::path::Path, file: &str, start: usize, end: usize) -> Option<String> {
    let content = std::fs::read_to_string(root.join(file)).ok()?;
    let lines: Vec<&str> = content.split('\n').collect();
    if start == 0 || end == 0 || start > lines.len() { return None; }
    let e = end.min(lines.len());
    let mut out: Vec<&str> = lines[start - 1..e].to_vec();
    while out.last().map(|l| l.is_empty()).unwrap_or(false) { out.pop(); }
    Some(out.join("\n") + "\n")
}

fn launch_repo_list(rows: Vec<(String, String, String)>) -> Result<(), GitTypeError> {
    ensure_terminal()?;
    tui::run_repo_list(rows)
}

fn launch_repo_play(rows: Vec<(String, String, String)>) -> Result<(), GitTypeError> {
    ensure_terminal()?;
    tui::run_repo_play(rows)
}

fn launch_trending() -> Result<(), GitTypeError> {
    ensure_terminal()?;
    tui::run_trending()
}
