fn simple_loop(app: &mut App, done: impl Fn(&App) -> bool) -> crate::error::AppResult<()> {
    crossterm::execute!(std::io::stdout(), ct::EnterAlternateScreen).ok();
    ct::enable_raw_mode().ok();
    let mut terminal = ratatui::init();
    loop {
        if done(app) { break; }
        terminal.draw(|f| render(f, app))?;
        if crossterm::event::poll(Duration::from_millis(50)).ok() == Some(true) {
            if let Ok(Event::Key(k)) = crossterm::event::read() {
                if k.kind == crossterm::event::KeyEventKind::Press {
                    match k.code {
                        KeyCode::Esc => { app.screen = Screen::Quit; }
                        KeyCode::Char('q') if app.screen == Screen::RepoPlay => { app.screen = Screen::Quit; }
                        KeyCode::Down | KeyCode::Char('j') => { app.repo_sel = (app.repo_sel + 1).min(app.repo_list.len().saturating_sub(1)); }
                        KeyCode::Up | KeyCode::Char('k') => { app.repo_sel = app.repo_sel.saturating_sub(1); }
                        KeyCode::Char(' ') | KeyCode::Enter => {
                            if app.screen == Screen::TrendingLang { app.screen = Screen::TrendingRepos; }
                        }
                        _ => {}
                    }
                }
            }
        }
        if app.screen == Screen::Quit { break; }
    }
    let _ = ratatui::restore();
    ct::disable_raw_mode().ok();
    crossterm::execute!(std::io::stdout(), ct::LeaveAlternateScreen).ok();
    Ok(())
}
